import React from "react";

/**
 * Personal Portfolio — Home layout
 *
 *  Font:         Poppins (loaded via Google Fonts in the injected <style>)
 *  Text sizes:   h1 36px | h2 20px | h3 16px | h4 14px | paragraph 12px
 *  Background:   #ECF1F4
 *  Stroke:       soft hairline, rgba(199,199,199,0.45)
 *  Corner radius:20px
 *  Widget pad:   20px
 *  Primary:      #3B82F6
 *  Drop shadow:  0px 6px 13px 0px rgba(122,122,122,0.10)
 *
 * Layout notes:
 *  - The left nav has no card/frame of its own on desktop; it's `position:
 *    fixed` so it never scrolls with the page. On tablet/mobile it collapses
 *    into a static top bar (see the media queries in GLOBAL_CSS below).
 *  - Projects / About / Contact / Certifications are nested inside ONE
 *    larger outer frame (see ContentGrid).
 *  - Hover/active states and the tools marquee are plain CSS (see
 *    GLOBAL_CSS) since inline styles can't express :hover or @media.
 *
 * Drop this component into any React (Vite/CRA/Next) project — no external
 * CSS framework required. The profile photo is embedded as a base64 data
 * URI so the file works immediately; swap PROFILE_IMAGE for your own
 * import/path whenever you like.
 */

const SIDEBAR_WIDTH = 260;

// ---------------------------------------------------------------------------
// Profile photo (swap this for your own import/path if you prefer an
// external file instead of an inline data URI)
// ---------------------------------------------------------------------------
const PROFILE_IMAGE =
  "data:image/jpeg;base64,";

// ---------------------------------------------------------------------------
// Global styles: font import, hover/active micro-interactions, the tools
// marquee animation, and tablet/mobile responsiveness.
// ---------------------------------------------------------------------------
const GLOBAL_CSS = `
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap');

/* ---------- Defensive reset ----------
   Neutralizes common Vite/CRA boilerplate (dark :root color-scheme, a
   centered #root with a max-width, body margin) that otherwise fights with
   this component when dropped into a freshly scaffolded project. */
html,
body,
#root {
  margin: 0;
  padding: 0;
  width: 100%;
  min-width: 100%;
  min-height: 100%;
  background: #ECF1F4;
}

html {
  background: #ECF1F4;
  overscroll-behavior-y: none;
}

body {
  background: #ECF1F4;
  background-attachment: fixed;
  overflow-x: hidden;
  overflow-y: auto;
}

#root {
  width: 100%;
  max-width: none !important;
  margin: 0;
  padding: 0;
  text-align: left;
}

.pf-root, .pf-root * { box-sizing: border-box; }
.pf-root {
  width: 100%;
  max-width: none;
  color-scheme: light;
  background: #ECF1F4;
  background-attachment: fixed;
  min-height: 100vh;
  font-family: 'Poppins', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #111318;
  text-align: left;
}
.pf-root h1, .pf-root h2, .pf-root h3, .pf-root h4, .pf-root p { color: inherit; margin: 0; }

/* ---------- Sidebar ---------- */
.pf-sidebar {
  position: fixed;
  top: 0;
  left: 0;
  width: 260px;
  height: 100vh;
  height: 100dvh;
  padding: 24px 24px 18px;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  background: transparent;
  z-index: 30;
}
.pf-sidebar::-webkit-scrollbar { display: none; }

.pf-photo-block { display: flex; flex-direction: column; align-items: center; }

.pf-photo-ring {
  width: 112px;
  height: 112px;
  border-radius: 50%;
  border: 3px solid #3B82F6;
  padding: 3px;
  flex-shrink: 0;
  transition: transform .35s cubic-bezier(.34,1.56,.64,1);
}
.pf-photo-ring:hover { transform: scale(1.05) rotate(2deg); }
.pf-photo-ring img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; display: block; }

.pf-name-col { display: flex; flex-direction: column; align-items: center; }
.pf-name-row { display: flex; align-items: center; gap: 6px; margin-top: 18px; }
.pf-name { font-size: 16px; font-weight: 700; margin: 0; }
.pf-name-row svg { width: 16px; height: 16px; flex-shrink: 0; }
.pf-subtitle { font-size: 12px; color: #6B7280; text-align: center; margin: 6px 0 0; line-height: 1.6; max-width: 210px; }

.pf-socials { display: flex; gap: 12px; margin-top: 18px; }
.pf-social {
  width: 34px; height: 34px; border-radius: 50%;
  border: 1px solid rgba(199,199,199,.45);
  background: #fff;
  display: flex; align-items: center; justify-content: center;
  color: #111318; text-decoration: none;
  transition: transform .3s cubic-bezier(.34,1.56,.64,1), box-shadow .3s ease, background .3s ease, color .3s ease;
}
.pf-social svg { width: 16px; height: 16px; }
.pf-social:hover { transform: translateY(-4px) scale(1.08); box-shadow: 0 8px 16px rgba(122,122,122,.2); background: #3B82F6; color: #fff; }
.pf-social:active { transform: translateY(-1px) scale(1.02); }

.pf-divider { width: 100%; height: 1px; background: rgba(199,199,199,.5); margin: 22px 0 18px; flex-shrink: 0; }

.pf-nav { width: 100%; display: flex; flex-direction: column; gap: 10px; }
.pf-nav-item {
  display: flex; align-items: center; gap: 12px; width: 100%;
  padding: 10px 12px; border-radius: 10px;
  border: 1px solid transparent; background: transparent;
  color: #8A8F98; cursor: pointer; text-align: left;
  font-family: inherit; font-size: 14px; font-weight: 500;
  transition: background .25s ease, color .25s ease, transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
.pf-nav-item svg { width: 20px; height: 20px; flex-shrink: 0; }
.pf-nav-item:hover { background: #fff; color: #111318; transform: translateX(4px); box-shadow: 0 6px 13px rgba(122,122,122,.10); }
.pf-nav-item.active { background: #fff; border-color: rgba(199,199,199,.45); box-shadow: 0 6px 13px rgba(122,122,122,.10); color: #111318; font-weight: 700; }
.pf-nav-item:active { transform: translateX(2px) scale(.98); }

/* Mobile-only nav toggle — hidden on desktop/tablet by default */
.pf-hamburger {
  display: none;
  width: 40px; height: 40px; border-radius: 12px; flex-shrink: 0;
  border: 1px solid rgba(199,199,199,.45); background: #fff; color: #111318;
  align-items: center; justify-content: center; cursor: pointer;
  transition: background .25s ease, color .25s ease, transform .2s ease;
}
.pf-hamburger svg { width: 20px; height: 20px; }
.pf-hamburger:hover { background: #3B82F6; color: #fff; }
.pf-hamburger:active { transform: scale(.92); }

.pf-spacer { flex: 1 1 auto; min-height: 12px; }

.pf-cv-wrap { width: 100%; }
/* Two copies of the CV action exist: one pinned near the sidebar's bottom
   (desktop), one nested inside the nav dropdown right after Contact
   (tablet/mobile). Only one is ever visible at a time — see the <=1024px
   block below. */
.pf-cv-wrap-inline { display: none; }
.pf-nav-cv-divider { display: none; }
.pf-cv-btn {
  width: 100%; background: #3B82F6; color: #fff; border: none; border-radius: 999px;
  padding: 13px 16px; display: flex; align-items: center; justify-content: center; gap: 10px;
  cursor: pointer; font-family: inherit; font-size: 14px; font-weight: 600;
  transition: transform .25s ease, box-shadow .25s ease, background .25s ease;
}
.pf-cv-btn svg { width: 18px; height: 18px; }
.pf-cv-btn:hover { transform: translateY(-3px); box-shadow: 0 12px 22px rgba(59,130,246,.35); background: #2f6fe0; }
.pf-cv-btn:active { transform: translateY(-1px) scale(.98); }

.pf-footer { font-size: 11px; color: #6B7280; margin: 10px 0 0; text-align: center; line-height: 1.45; flex-shrink: 0; }
/* Tablet/mobile only: once the sidebar becomes a top header, its own
   .pf-footer is hidden and this copy — rendered at the very end of <main>,
   after all page content — takes over, so the copyright always sits at the
   true bottom of whichever page is showing. Hidden on desktop, where the
   sidebar's own footer (pinned via .pf-spacer) already does the job. */
.pf-footer-mobile { display: none; font-size: 11px; color: #6B7280; text-align: center; line-height: 1.45; margin: 32px 0 0; }

/* ---------- Main ---------- */
.pf-main {
  margin-left: 260px;
  width: calc(100% - 260px);
  min-height: 100vh;
  padding: 28px;
  position: relative;
  z-index: 1;
}

/* ---------- Decorative floating background icons ----------
   Purely visual, sits behind the sidebar (z-index:30) and the
   main content (z-index:1 above) via position:fixed + z-index:0,
   so it never intercepts clicks (pointer-events:none) and never
   competes with real content. Icons reuse the existing Icon set,
   colored close to the page background (#ECF1F4) so the whole
   layer stays a barely-there texture rather than a visible motif. */
.pf-floating-icons {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  color: rgba(59, 130, 246, 0.16);
}
.pf-floating-icon {
  position: absolute;
  animation: pf-float-drift linear infinite;
  will-change: transform;
}
.pf-floating-icon svg { display: block; width: 100%; height: 100%; }
@keyframes pf-float-drift {
  0%   { transform: translate(0, 0) rotate(0deg); }
  20%  { transform: translate(var(--dx), var(--dy)) rotate(var(--dr)); }
  45%  { transform: translate(calc(var(--dx) * 1.7), calc(var(--dy) * -0.5)) rotate(calc(var(--dr) * -1)); }
  70%  { transform: translate(calc(var(--dx) * 0.4), calc(var(--dy) * 1.6)) rotate(var(--dr)); }
  90%  { transform: translate(calc(var(--dx) * -0.8), calc(var(--dy) * 0.3)) rotate(calc(var(--dr) * -0.6)); }
  100% { transform: translate(0, 0) rotate(0deg); }
}

.pf-hero h1 { font-size: 36px; font-weight: 800; line-height: 1.25; margin: 0; }
.pf-hero p { font-size: 14px; color: #4B5563; margin-top: 14px; line-height: 1.7; max-width: 640px; }
.pf-hero-divider { height: 1px; background: rgba(199,199,199,.5); margin-top: 22px; }

.pf-card {
  background: #fff; border: 1px solid rgba(199,199,199,.45); border-radius: 20px;
  box-shadow: 0 6px 13px rgba(122,122,122,.10); padding: 20px;
  transition: transform .3s ease, box-shadow .3s ease;
}
.pf-card:hover { transform: translateY(-4px); box-shadow: 0 16px 30px rgba(122,122,122,.16); }

.pf-tools-bar { display: flex; align-items: center; gap: 28px; margin-top: 20px; }
.pf-tools-heading { min-width: 180px; flex-shrink: 0; }
.pf-tools-heading h2 { font-size: 20px; font-weight: 700; color: #3B82F6; margin: 0; }
.pf-tools-heading p { font-size: 12px; color: #6B7280; margin: 6px 0 0; }
.pf-tools-divider { width: 1px; align-self: stretch; background: rgba(199,199,199,.5); flex-shrink: 0; }

.pf-marquee-wrap {
  flex: 1; min-width: 0; overflow: hidden;
  -webkit-mask-image: linear-gradient(to right, transparent, black 6%, black 94%, transparent);
  mask-image: linear-gradient(to right, transparent, black 6%, black 94%, transparent);
}
.pf-marquee-track { display: flex; gap: 14px; width: max-content; animation: pf-marquee 32s linear infinite; }
.pf-marquee-wrap:hover .pf-marquee-track { animation-play-state: paused; }
@keyframes pf-marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }

.pf-tool-chip {
  display: flex; align-items: center; gap: 10px; flex: 0 0 auto;
  padding: 10px 16px; border-radius: 14px;
  border: 1px solid rgba(199,199,199,.45); background: #fff;
  transition: transform .25s ease, box-shadow .25s ease, border-color .25s ease;
}
.pf-tool-chip svg { width: 28px; height: 28px; flex-shrink: 0; border-radius: 7px; }
.pf-tool-chip span { font-size: 14px; font-weight: 600; white-space: nowrap; }
.pf-tool-chip:hover { transform: translateY(-3px) scale(1.05); box-shadow: 0 10px 18px rgba(122,122,122,.18); border-color: #3B82F6; }

.pf-content-grid { margin-top: 20px; padding: 20px; }
.pf-blank-section { margin-top: 20px; min-height: 320px; }

/* ---------- Contact: click-to-open envelope + letter form ---------- */
.pf-contact-stage { margin-top: 32px; }

.pf-envelope-scene { perspective: 1900px; }

/* One continuous envelope, one fixed size, for every stage — closed,
   opening, open and sending all share the exact same card footprint.
   Nothing grows or shrinks between states: only the flap rotates and
   the content inside crossfades between the "click to open" teaser and
   the letter form. That's deliberate — a card that changes height when
   it opens doesn't read as an envelope, it reads as two different
   elements swapped for each other. */
.pf-envelope-body {
  position: relative; width: 100%; max-width: 640px; margin: 0;
  animation: pf-fade-up .4s ease both;
}
.stage-closed .pf-envelope-body { cursor: pointer; }
.stage-closed .pf-envelope-body:focus-visible .pf-envelope-shell { outline: 2px solid #3B82F6; outline-offset: 4px; }

.pf-envelope-shell {
  position: relative; height: 630px; border-radius: 22px; overflow: hidden;
  background: linear-gradient(170deg, #3B82F6 0%, #2f6fe0 100%);
  box-shadow: 0 14px 30px rgba(59,130,246,.14), 0 4px 10px rgba(122,122,122,.08);
  transition: transform .3s ease, box-shadow .3s ease;
}
.stage-closed .pf-envelope-body:hover .pf-envelope-shell {
  transform: translateY(-5px);
  box-shadow: 0 20px 38px rgba(59,130,246,.22), 0 6px 14px rgba(122,122,122,.1);
}

/* The header band is deliberately tall (a third of the card) so the
   flap opening is a real, obvious motion rather than a small strip
   tipping over. The flap's rotation is a 3D transform, and a steep
   angle plus perspective can make it visually swing upward past the
   top of the card while mid-rotation — pf-envelope-frame clips that to
   this band so the flap tucks away behind the card instead of ever
   escaping the shell, however tall it is or however it rotates. */
.pf-envelope-frame {
  position: absolute; top: 0; left: 0; right: 0; height: 195px; overflow: hidden; z-index: 2;
}
.pf-envelope-back {
  position: absolute; inset: 0; z-index: 1;
  background: transparent;
}

/* Sitting behind the flap, revealed only once it swings open — like
   something printed on the inside of a real envelope you only see
   after opening it. This is what makes the opening motion register:
   the flap swinging away has a visible payoff, not just an empty blue
   band underneath. It must stay fully invisible while closed — the
   flap only covers its own triangular silhouette (via clip-path), so
   anything behind it that isn't also hidden by opacity peeks out
   around the triangle's edges. */
.pf-envelope-open-title {
  position: absolute; inset: 0; z-index: 2;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  color: #fff; text-align: center; padding: 0 32px;
  opacity: 0; transition: opacity .3s ease .25s;
}
.stage-open .pf-envelope-open-title,
.stage-sending .pf-envelope-open-title {
  opacity: 1;
}
.pf-envelope-open-title svg { width: 28px; height: 28px; margin-bottom: 8px; }
.pf-envelope-open-title h3 { font-size: 17px; font-weight: 800; margin: 0; }
.pf-envelope-open-title p { font-size: 13px; color: rgba(255,255,255,.82); margin: 6px 0 0; }

/* The flap sits on top of the envelope back, folded shut like a real
   envelope, with a round seal badge at its point. Opening it rotates it
   back (transform-origin at its base) so it swings out of the way —
   backface-visibility keeps it from showing a mirrored front once it
   passes vertical, so it cleanly disappears instead of flickering. A
   modest -112deg (just past vertical) keeps the motion contained
   instead of swinging dramatically upward. */
.pf-envelope-flap {
  position: absolute; inset: 0; z-index: 3;
  background: linear-gradient(160deg, #5b96f5 0%, #4a86ef 100%);
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  transform-origin: top center; transform-style: preserve-3d; backface-visibility: hidden;
  transform: rotateX(0deg);
  transition: transform .7s cubic-bezier(.22,1,.36,1);
  box-shadow: 0 4px 10px rgba(17,19,24,.12);
}
.stage-opening .pf-envelope-flap,
.stage-open .pf-envelope-flap,
.stage-sending .pf-envelope-flap {
  transform: rotateX(-112deg);
}


/* Below the header band: the same fixed-size crossfade as the header
   above it. The teaser keeps the header's blue so the closed envelope
   reads as one solid card (not a blue header sitting on a white body),
   and the letter form fades in over it, in white, once opened. */
.pf-envelope-content { position: absolute; top: 195px; left: 0; right: 0; bottom: 0; }

.pf-envelope-caption {
  position: absolute; inset: 0; z-index: 2;
  display: flex; flex-direction: column; justify-content: center; align-items: center;
  padding: 0 44px; text-align: center; color: #fff;
  background: transparent;
  opacity: 1; transition: opacity .3s ease;
}
.stage-opening .pf-envelope-caption,
.stage-open .pf-envelope-caption,
.stage-sending .pf-envelope-caption {
  opacity: 0; pointer-events: none;
}
.pf-envelope-caption h3 { font-size: 22px; font-weight: 800; margin: 0; }
.pf-envelope-caption p {
  font-size: 14px; color: rgba(255,255,255,.88); line-height: 1.6; margin: 10px 0 0; max-width: 420px;
}
.pf-envelope-caption p a {
  color: #fff; font-weight: 700; text-decoration: underline; text-underline-offset: 2px;
}

.pf-letter-paper {
  position: absolute; inset: 0; z-index: 1; overflow-y: auto;
  background: #fff; padding: 22px 32px 26px;
  opacity: 0; transform: translateY(-14px);
  transition: opacity .4s ease, transform .4s ease;
  pointer-events: none;
}
.stage-open .pf-letter-paper,
.stage-sending .pf-letter-paper {
  opacity: 1; transform: translateY(0); pointer-events: auto;
}

.pf-letter-form { display: flex; flex-direction: column; gap: 11px; }
.pf-letter-field { display: flex; flex-direction: column; gap: 5px; }
.pf-letter-field span { font-size: 13px; font-weight: 700; color: #6B7280; }
.pf-letter-field input, .pf-letter-field textarea {
  font-family: inherit; font-size: 15px; color: #111318;
  border: 1px solid rgba(199,199,199,.5); border-radius: 12px;
  padding: 11px 14px; background: #fff; resize: vertical;
  transition: border-color .2s ease, box-shadow .2s ease;
}
.pf-letter-field input:focus, .pf-letter-field textarea:focus {
  outline: none; border-color: #3B82F6; box-shadow: 0 0 0 3px rgba(59,130,246,.15);
}
.pf-letter-field input:disabled, .pf-letter-field textarea:disabled { opacity: .6; }
.pf-contact-error { font-size: 13px; color: #DC2626; margin: -4px 0 0; }

.pf-letter-actions { display: flex; align-items: center; justify-content: flex-end; gap: 14px; margin-top: 12px; }
.pf-letter-cancel {
  font-family: inherit; font-size: 14px; font-weight: 600; color: #6B7280;
  background: none; border: none; cursor: pointer; padding: 8px 4px;
  transition: color .2s ease;
}
.pf-letter-cancel:hover { color: #111318; }
.pf-letter-cancel:disabled { opacity: .5; cursor: default; }
.pf-send-btn { width: auto; padding: 14px 28px; font-size: 15px; }
.pf-send-btn:disabled { opacity: .75; cursor: default; transform: none; box-shadow: none; }

/* Sending: a little "paper plane" pops up from the letter and flies off,
   standing in for the message being sent on its way. */
.pf-envelope-paper-plane {
  position: absolute; left: 50%; bottom: 30%; z-index: 5;
  width: 52px; height: 52px; border-radius: 50%;
  background: #3B82F6; color: #fff;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 10px 22px rgba(59,130,246,.4);
  animation: pf-plane-fly 1.1s ease forwards;
}
.pf-envelope-paper-plane svg { width: 24px; height: 24px; }
@keyframes pf-plane-fly {
  0% { transform: translate(-50%, 0) scale(.7) rotate(0deg); opacity: 0; }
  18% { opacity: 1; transform: translate(-50%, 0) scale(1) rotate(0deg); }
  100% { transform: translate(140%, -260%) scale(.55) rotate(28deg); opacity: 0; }
}

.pf-contact-confirm {
  width: 100%; max-width: 640px; margin: 0 auto; display: flex; flex-direction: column;
  align-items: center; text-align: center; gap: 12px; padding: 52px 32px;
  background: #fff; border: 1px solid rgba(199,199,199,.45); border-radius: 20px;
  box-shadow: 0 6px 13px rgba(122,122,122,.10);
  animation: pf-fade-up .45s ease both;
}
.pf-confirm-check {
  width: 68px; height: 68px; border-radius: 50%; flex-shrink: 0;
  background: rgba(59,130,246,.08); color: #3B82F6;
  display: flex; align-items: center; justify-content: center;
}
.pf-confirm-check svg { width: 36px; height: 36px; }
.pf-confirm-check path {
  stroke-dasharray: 14; stroke-dashoffset: 14;
  animation: pf-check-draw .4s .15s ease forwards;
}
@keyframes pf-check-draw { to { stroke-dashoffset: 0; } }
.pf-contact-confirm h3 { font-size: 20px; font-weight: 800; margin: 6px 0 0; color: #111318; }
.pf-contact-confirm p { font-size: 14px; color: #6B7280; line-height: 1.7; margin: 0; max-width: 360px; }
.pf-contact-again {
  width: auto; margin-top: 10px; padding: 13px 26px;
}
.pf-contact-again svg { width: 18px; height: 18px; }

/* ---------- Contact modal ---------- */
/* The envelope opens as a dialog over whatever page is showing, rather than
   being a page of its own. Fade + scale on both the backdrop and the panel;
   visibility is driven by the .is-visible class the component adds a frame
   after mounting (see ContactModal), so the transition has a starting state
   to animate from instead of just appearing instantly. */
.pf-contact-modal {
  position: fixed; inset: 0; z-index: 200;
  display: flex; align-items: flex-start; justify-content: center; padding: 40px 24px;
  overflow-y: auto;
  background: rgba(17,19,24,0);
  opacity: 0;
  transition: opacity .25s ease, background-color .25s ease;
}
.pf-contact-modal.is-visible {
  opacity: 1; background: rgba(17,19,24,.55);
}
.pf-contact-modal-panel {
  position: relative; width: 100%; max-width: 640px; margin: auto;
  transform: scale(.94) translateY(10px);
  transition: transform .3s cubic-bezier(.22,1,.36,1);
}
.pf-contact-modal.is-visible .pf-contact-modal-panel {
  transform: scale(1) translateY(0);
}
/* ContactSection is designed to sit under a page heading normally, so drop
   the top margin it'd otherwise add here at the top of the modal. */
.pf-contact-modal-panel .pf-contact-stage { margin-top: 0; }
.pf-contact-modal-close {
  position: absolute; top: -14px; right: -14px; z-index: 5;
  width: 40px; height: 40px; border-radius: 50%; border: none;
  background: #fff; color: #111318; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 8px 20px rgba(17,19,24,.25);
  transition: transform .2s ease, background .2s ease;
}
.pf-contact-modal-close:hover { transform: scale(1.08); background: #f3f4f6; }
.pf-contact-modal-close:focus-visible { outline: 2px solid #3B82F6; outline-offset: 2px; }
.pf-contact-modal-close svg { width: 18px; height: 18px; }

/* ---------- Tools section (interactive filter + flip cards) ---------- */
.pf-tools-section { display: flex; flex-direction: column; gap: 20px; margin-top: 20px; }

.pf-filter-row { display: flex; flex-wrap: wrap; gap: 10px; }
.pf-filter-chip {
  padding: 9px 18px; border-radius: 999px; border: 1px solid rgba(199,199,199,.45);
  background: #fff; color: #6B7280; font-family: inherit; font-size: 14px; font-weight: 600;
  cursor: pointer; transition: transform .25s ease, box-shadow .25s ease, background .25s ease, color .25s ease, border-color .25s ease;
}
.pf-filter-chip:hover { border-color: #3B82F6; color: #111318; transform: translateY(-2px); }
.pf-filter-chip.active { background: #3B82F6; border-color: #3B82F6; color: #fff; box-shadow: 0 8px 16px rgba(59,130,246,.3); }
.pf-filter-chip:active { transform: translateY(0) scale(.97); }

.pf-tools-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 18px; }

.pf-tool-card {
  position: relative; height: 190px; perspective: 1200px;
  background: none; border: none; padding: 0; cursor: pointer; font-family: inherit;
  opacity: 0; animation: pf-fade-up .5s ease forwards;
}
.pf-tool-card:focus-visible { outline: 2px solid #3B82F6; outline-offset: 4px; border-radius: 16px; }

@keyframes pf-fade-up {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

.pf-tool-card-inner {
  position: relative; width: 100%; height: 100%;
  transition: transform .55s cubic-bezier(.4,0,.2,1);
  transform-style: preserve-3d;
}
.pf-tool-card.flipped .pf-tool-card-inner { transform: rotateY(180deg); }

.pf-tool-card-face {
  position: absolute; inset: 0; backface-visibility: hidden; border-radius: 16px;
  border: 1px solid rgba(199,199,199,.45); background: #fff;
  box-shadow: 0 6px 13px rgba(122,122,122,.10);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 10px; padding: 18px; text-align: center;
  transition: box-shadow .3s ease, transform .3s ease;
}
.pf-tool-card:hover:not(.flipped) .pf-tool-card-front { transform: translateY(-4px); box-shadow: 0 14px 26px rgba(122,122,122,.18); }

.pf-tool-card-icon { width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; transition: transform .3s ease; }
.pf-tool-card-icon svg, .pf-tool-card-icon img { width: 100%; height: 100%; object-fit: contain; border-radius: 9px; }
.pf-tool-card:hover:not(.flipped) .pf-tool-card-icon { transform: scale(1.12) rotate(-6deg); }

.pf-tool-card-front h3 { font-size: 15px; font-weight: 700; margin: 0; }
.pf-tool-card-tag {
  font-size: 11px; font-weight: 700; color: #3B82F6; background: rgba(59,130,246,.1);
  padding: 4px 10px; border-radius: 999px; letter-spacing: .03em; text-transform: uppercase;
}

.pf-tool-card-back { background: #3B82F6; border-color: #3B82F6; transform: rotateY(180deg); }
.pf-tool-card-back p { color: #fff; font-size: 12.5px; line-height: 1.6; margin: 0; }

.pf-fav-btn {
  position: absolute; top: 10px; right: 10px; z-index: 2; width: 28px; height: 28px; border-radius: 50%;
  border: none; background: rgba(255,255,255,.9); display: flex; align-items: center; justify-content: center;
  color: #C7C7C7; cursor: pointer; transition: transform .2s ease, color .2s ease;
}
.pf-fav-btn svg { width: 15px; height: 15px; }
.pf-fav-btn:hover { transform: scale(1.18); color: #F5B301; }
.pf-fav-btn.active { color: #F5B301; }
.pf-tool-card.flipped .pf-fav-btn { display: none; }
/* Row 1's height is pinned to match ABOUT/CONTACT's own fixed height
   (see .pf-widget-about / .pf-widget-contact below — keep these in sync).
   PROJECTS spans both rows, and with row 1 left as "auto" its own taller
   natural content would pull row 1 past that fixed height to fit, leaving
   ABOUT/CONTACT sitting at the top of an over-tall row with a gap of dead
   space beneath them before CERTIFICATIONS starts — the uneven spacing
   this fixes. Any extra height PROJECTS still needs beyond that spills
   into row 2 (auto), which just makes the CERTIFICATIONS card a little
   taller rather than reopening a stray gap.

   380px (not 330px) specifically because CONTACT's own content — the
   envelope (capped at 300x187.5 by .pf-contact-mini's own width cap) plus
   the quick-email card below it, with that card's real padding/icon/text/
   button — needs roughly that much room. At 330px the quick-email card's
   own box was shorter than its content actually needed, and since it
   clips overflow (rather than growing past the fixed-height column and
   distorting the row), the result was its icon and button visibly cut
   off at the card's rounded edges instead of sitting inside it. */
.pf-grid-inner { display: grid; grid-template-columns: 1.5fr 1fr 1fr; grid-template-rows: 380px auto; gap: 20px; }

.pf-widget-projects { grid-column: 1; grid-row: 1 / 3; }
.pf-widget-about { grid-column: 2; grid-row: 1; height: 380px; }
.pf-widget-contact {
  grid-column: 3; grid-row: 1; height: 380px;
  display: flex; flex-direction: column; align-items: center; justify-content: flex-start; gap: 14px;
}
.pf-widget-cert { grid-column: 2 / 4; grid-row: 2; }

.pf-widget { display: flex; flex-direction: column; gap: 14px; }
.pf-widget-header { display: flex; align-items: center; gap: 10px; }
.pf-widget-badge {
  width: 32px; height: 32px; border-radius: 9px; background: #3B82F6;
  display: flex; align-items: center; justify-content: center; color: #fff;
  flex-shrink: 0; transition: transform .3s ease;
}
.pf-widget-badge svg { width: 18px; height: 18px; }
/* Scoped to .pf-widget (each widget's own card), not the broader .pf-card —
   ContentGrid's outer section is also a .pf-card, and since :hover applies
   to an element whenever any descendant is hovered, a plain ".pf-card:hover"
   descendant selector here would fire for every widget at once as soon as
   any one of them was hovered. */
.pf-widget:hover .pf-widget-badge { transform: rotate(-8deg) scale(1.08); }
.pf-widget-header h2 { font-size: 20px; font-weight: 700; letter-spacing: .02em; margin: 0; }
.pf-widget-desc { font-size: 12px; color: #6B7280; line-height: 1.6; margin: 0; }

.pf-placeholder {
  height: 100%; width: 100%; background: #DADFE3; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  transition: background .3s ease;
}
.pf-placeholder span { font-size: 14px; font-weight: 600; color: #111318; letter-spacing: .02em; text-align: center; padding: 0 12px; }
.pf-widget:hover .pf-placeholder { background: #CDD5DB; }

/* Widgets that link out to a full page (About, Certifications) wrap their
   preview media in this, so hovering the whole card reveals a single CTA
   over the media instead of a second, competing block of text. */
.pf-widget-media { position: relative; display: flex; flex-direction: column; gap: 14px; flex: 1; }
.pf-widget-media-overlay {
  position: absolute; inset: 0; z-index: 3; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
  background: rgba(17,19,24,0); opacity: 0; pointer-events: none;
  transition: opacity .25s ease, background-color .25s ease;
}
.pf-widget:hover .pf-widget-media-overlay {
  opacity: 1; background: rgba(17,19,24,.45); pointer-events: auto;
}
.pf-widget-media-btn {
  display: inline-flex; align-items: center; gap: 8px;
  background: #fff; color: #111318; border: none; border-radius: 999px;
  padding: 10px 18px; font-family: inherit; font-size: 13px; font-weight: 700;
  cursor: pointer; transform: translateY(8px); opacity: 0;
  transition: transform .25s ease, opacity .25s ease, box-shadow .2s ease;
  box-shadow: 0 10px 20px rgba(17,19,24,.25);
}
.pf-widget:hover .pf-widget-media-btn { transform: translateY(0); opacity: 1; }
.pf-widget-media-btn:hover { box-shadow: 0 14px 26px rgba(17,19,24,.32); }
.pf-widget-media-btn svg { width: 14px; height: 14px; }

/* Certifications preview — a flush filmstrip of edge-to-edge thumbnails
   (no rotation, no card border around each one) so it reads as one
   continuous strip rather than separate floating tiles. Each tile carries
   its own bold caption directly on the image via a bottom gradient, and
   zooms slightly on hover — the strip itself is rounded and clipped as one
   piece, with a hairline gap between tiles standing in for a seam. */
.pf-widget-cert-strip {
  height: 130px; display: flex; gap: 3px;
  border-radius: 14px; overflow: hidden;
  box-shadow: 0 10px 22px rgba(17,19,24,.16);
}
.pf-widget-cert-thumb {
  position: relative; flex: 1; min-width: 0; overflow: hidden; background: #DADFE3;
}
.pf-widget-cert-thumb img {
  width: 100%; height: 100%; object-fit: cover; display: block;
  transition: transform .35s ease;
}
.pf-widget:hover .pf-widget-cert-thumb img { transform: scale(1.08); }
.pf-widget-cert-thumb-caption {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 1;
  padding: 10px 10px 9px;
  background: linear-gradient(180deg, rgba(17,19,24,0) 40%, rgba(17,19,24,.8) 100%);
}
.pf-widget-cert-thumb-caption span {
  display: block; color: #fff; font-size: 11px; font-weight: 800; letter-spacing: .01em;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.pf-widget-cert-more {
  position: absolute; top: 8px; right: 8px; z-index: 2;
  background: #3B82F6; color: #fff; font-size: 10.5px; font-weight: 800;
  padding: 4px 8px; border-radius: 999px;
  box-shadow: 0 4px 10px rgba(59,130,246,.35);
}

/* Home page's ABOUT and CONTACT widgets, sitting side by side, share one
   fixed height (set on .pf-widget-about / .pf-widget-contact above) so the
   row lines up cleanly instead of one stretching to match the other's
   natural content height. Both are "the media is the card": no separate
   .pf-card wrapper, header or description around them. */

/* ABOUT — a photo widget: one "outside the work" photo/gif at a time,
   cross-fading, with the heading/blurb/CTA sitting in a gradient overlay
   on top of it rather than above a separate strip of thumbnails. */
.pf-about-mini {
  position: relative; width: 100%; height: 100%;
  border-radius: 20px; overflow: hidden;
  border: none; padding: 0; cursor: pointer; font-family: inherit; text-align: left;
  background: #111318;
  box-shadow: 0 6px 13px rgba(122,122,122,.10);
  transition: transform .25s ease, box-shadow .25s ease;
}
.pf-about-mini:hover { transform: translateY(-4px); box-shadow: 0 16px 30px rgba(122,122,122,.16); }
.pf-about-mini:focus-visible { outline: 2px solid #3B82F6; outline-offset: 3px; }
.pf-about-mini-media { position: absolute; inset: 0; z-index: 0; display: block; }
.pf-about-mini-img {
  position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover;
  opacity: 0; transition: opacity .8s ease;
}
.pf-about-mini-img.is-active { opacity: 1; }
.pf-about-mini-overlay {
  position: absolute; inset: 0; z-index: 1;
  display: flex; flex-direction: column; justify-content: flex-end;
  padding: 20px; color: #fff;
  background: linear-gradient(180deg, rgba(17,19,24,0) 30%, rgba(17,19,24,.82) 100%);
}
.pf-about-mini-header { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.pf-about-mini-icon {
  width: 28px; height: 28px; border-radius: 8px; background: rgba(255,255,255,.2);
  display: flex; align-items: center; justify-content: center; color: #fff; flex-shrink: 0;
}
.pf-about-mini-icon svg { width: 16px; height: 16px; }
.pf-about-mini-header h3 { font-size: 17px; font-weight: 800; margin: 0; letter-spacing: .02em; }
.pf-about-mini-overlay p {
  font-size: 13px; line-height: 1.55; color: rgba(255,255,255,.9); margin: 0 0 14px; max-width: 300px;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.pf-about-mini-btn {
  display: inline-flex; align-items: center; gap: 8px; align-self: flex-start;
  background: #fff; color: #111318; border-radius: 999px;
  padding: 10px 18px; font-size: 13px; font-weight: 700;
}
.pf-about-mini-btn svg { width: 14px; height: 14px; }

/* CONTACT — the envelope itself. Its slot (.pf-widget-contact, a flex
   container) is the same height as ABOUT's for a clean, even row, but a
   real envelope only reads as an envelope in landscape, so the envelope
   keeps its own wider-than-tall ratio and centers itself in that slot
   rather than stretching edge to edge like the ABOUT photo does.

   width: min(100%, 300px) is load-bearing, not cosmetic: this slot's
   column isn't the same width at every breakpoint (three narrower columns
   on desktop, two wider ones on tablet), but the envelope's HEIGHT is
   always dictated by its width via aspect-ratio. Left at a plain 100%,
   the envelope alone grows taller than this slot's whole height budget at
   the wider tablet breakpoint, well before the quick-email card below it
   even enters the picture — the exact overflow bug this fixes. Capping
   the width keeps the envelope's height predictable everywhere. */
.pf-contact-mini {
  position: relative; width: min(100%, 300px); aspect-ratio: 8 / 5; flex-shrink: 0;
  border-radius: 20px; overflow: hidden;
  border: none; padding: 0; cursor: pointer; font-family: inherit;
  background: linear-gradient(170deg, #3B82F6 0%, #2f6fe0 100%);
  box-shadow: 0 6px 13px rgba(59,130,246,.18);
  transition: transform .25s cubic-bezier(.22,1,.36,1), box-shadow .25s ease;
}
.pf-contact-mini:hover { transform: translateY(-4px); box-shadow: 0 16px 30px rgba(59,130,246,.3); }
.pf-contact-mini:focus-visible { outline: 2px solid #3B82F6; outline-offset: 3px; }
.pf-contact-mini.is-growing { transform: scale(1.05); box-shadow: 0 20px 36px rgba(59,130,246,.34); }
.pf-contact-mini-flap {
  position: absolute; top: 0; left: 0; right: 0; height: 62%;
  background: linear-gradient(160deg, #5b96f5 0%, #4a86ef 100%);
  clip-path: polygon(0 0, 100% 0, 50% 100%);
}
/* No icon or caption on the envelope itself anymore — it reads as an
   envelope by its shape alone. Instead, hovering reveals a small red
   "unread" badge in the top-right corner with a tooltip, the same
   attention-getting language as an unread-message indicator. */
.pf-contact-mini-badge {
  position: absolute; top: 12px; right: 12px; z-index: 2;
  width: 15px; height: 15px; border-radius: 50%;
  background: #EF4444; border: 2px solid #fff;
  box-shadow: 0 2px 6px rgba(17,19,24,.3);
  opacity: 0; transform: scale(.4);
  transition: opacity .25s ease, transform .25s ease;
}
.pf-contact-mini:hover .pf-contact-mini-badge { opacity: 1; transform: scale(1); }
.pf-contact-mini-badge::after {
  content: ""; position: absolute; inset: -5px; border-radius: 50%;
  border: 2px solid rgba(239,68,68,.55);
  animation: pf-badge-pulse 1.7s ease-out infinite;
}
@keyframes pf-badge-pulse {
  0% { transform: scale(.6); opacity: .8; }
  100% { transform: scale(2); opacity: 0; }
}
.pf-contact-mini-tooltip {
  position: absolute; top: 11px; right: 34px; z-index: 2;
  background: #111318; color: #fff; font-size: 12px; font-weight: 700;
  padding: 7px 14px; border-radius: 8px; white-space: nowrap;
  box-shadow: 0 8px 16px rgba(17,19,24,.25);
  opacity: 0; transform: translateX(8px); pointer-events: none;
  transition: opacity .25s ease, transform .25s ease;
}
.pf-contact-mini-tooltip::after {
  content: ""; position: absolute; top: 50%; right: -5px; transform: translateY(-50%);
  border-width: 5px 0 5px 5px; border-style: solid; border-color: transparent transparent transparent #111318;
}
.pf-contact-mini:hover .pf-contact-mini-tooltip { opacity: 1; transform: translateX(0); }

/* A small quick-action card sitting under the envelope — a real shortcut
   (copy the email address without opening the modal at all) rather than a
   status readout nobody asked for. It's the second (and last) item in the
   envelope's own flex column, so flex: 1 lets it grow and claim whatever
   height is left in that 380px slot instead of floating in a tall gap.
   Clicking "Copy email" swaps the whole card over to a confirmation view
   (check-draw + a plain-language message) rather than just flipping one
   small icon, since there's now real room for that — then swaps back on
   its own a few seconds later.

   min-height: 0 is load-bearing: without it, a flex item's minimum size
   defaults to its content's natural size, so if the success message's
   text ever needed more room than this card's flex-computed share, the
   browser would shrink the OTHER item in this column (the envelope
   button, which has no flex-shrink: 0 override without .pf-contact-mini's
   own rule below) to make room instead of just clipping this card's own
   overflow — visibly squashing the envelope out of its aspect ratio.
   min-height: 0 + overflow: hidden here keep any overflow local to this
   card instead of stealing space from the envelope. */
.pf-contact-quick {
  flex: 1; width: 100%; min-height: 0; overflow: hidden;
  display: flex; flex-direction: column; align-items: center;
  justify-content: center; text-align: center; gap: 8px;
  /* Plain white card — the same background/border/shadow every other card
     on this page uses (.pf-card, .pf-widget-cert-strip's own tiles, etc.),
     not a one-off gradient treatment. */
  background: #fff; border: 1px solid rgba(199,199,199,.45); border-radius: 16px;
  padding: 16px 18px; box-shadow: 0 6px 13px rgba(122,122,122,.10);
}
/* Same solid-blue icon-badge already used for every widget's own header
   icon (.pf-widget-badge — PROJECTS, CERTIFICATIONS, etc.), reused here
   rather than inventing a different treatment for this one icon. */
.pf-contact-quick-icon {
  width: 32px; height: 32px; border-radius: 9px; flex-shrink: 0;
  background: #3B82F6; color: #fff;
  display: flex; align-items: center; justify-content: center;
}
.pf-contact-quick-icon svg { width: 18px; height: 18px; }
.pf-contact-quick-text { display: flex; flex-direction: column; align-items: center; gap: 5px; max-width: 100%; }
.pf-contact-quick-text strong { font-size: 13.5px; font-weight: 800; color: #111318; }
.pf-contact-quick-email {
  display: inline-flex; align-items: center; font-size: 10.5px; font-weight: 700; color: #3B82F6;
  background: rgba(59,130,246,.1); border-radius: 999px; padding: 5px 12px;
  max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.pf-contact-quick-copy {
  display: inline-flex; align-items: center; gap: 7px; margin-top: 2px;
  background: #3B82F6; color: #fff; border: none; border-radius: 999px;
  padding: 9px 18px; font-family: inherit; font-size: 12px; font-weight: 700;
  cursor: pointer; box-shadow: 0 8px 16px rgba(59,130,246,.25);
  transition: transform .2s ease, box-shadow .2s ease;
}
.pf-contact-quick-copy:hover { transform: translateY(-2px); box-shadow: 0 12px 22px rgba(59,130,246,.32); }
.pf-contact-quick-copy:active { transform: scale(.96); }
.pf-contact-quick-copy svg { width: 14px; height: 14px; }

/* The confirmation view that replaces the above once copied — same
   check-draw language as the "Message sent!" confirmation screen
   (.pf-confirm-check), so a successful copy reads as the same kind of
   moment as a successful send. */
.pf-contact-quick-success {
  display: flex; flex-direction: column; align-items: center; gap: 10px;
  animation: pf-quick-success-in .35s cubic-bezier(.34,1.56,.64,1) both;
}
.pf-contact-quick-success-icon {
  width: 42px; height: 42px; border-radius: 50%; flex-shrink: 0;
  background: rgba(59,130,246,.1); color: #3B82F6;
  display: flex; align-items: center; justify-content: center;
}
.pf-contact-quick-success-icon svg { width: 21px; height: 21px; }
.pf-contact-quick-success-icon path {
  stroke-dasharray: 14; stroke-dashoffset: 14;
  animation: pf-check-draw .4s .1s ease forwards;
}
.pf-contact-quick-success p {
  font-size: 12.5px; line-height: 1.6; color: #4B5563; margin: 0; max-width: 230px;
}
@keyframes pf-quick-success-in {
  0% { opacity: 0; transform: scale(.9) translateY(6px); }
  100% { opacity: 1; transform: scale(1) translateY(0); }
}

/* ---------- About page ---------- */
.pf-about-page { display: flex; flex-direction: column; gap: 28px; margin-top: 20px; }
.pf-about-body { display: flex; flex-direction: column; gap: 28px; animation: pf-fade-up .5s ease both; }

/* One big frame holds every About sub-section (except the profile banner),
   matching the Home page's single-outer-card pattern. */
.pf-about-frame { display: flex; flex-direction: column; gap: 22px; }

/* Experience + Career timeline sit side by side on wide screens */
.pf-about-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; align-items: stretch; }

/* LinkedIn-style banner card — no avatar, identity carried by name + role */
.pf-about-banner { padding: 0; overflow: hidden; }
.pf-banner-strip {
  position: relative; height: 120px; overflow: hidden;
  background: linear-gradient(135deg, #3B82F6 0%, #2f6fe0 55%, #1d4ed8 100%);
  background-size: 220% 220%; background-position: 0% 50%;
  transition: background-position .6s ease;
}
.pf-about-banner:hover .pf-banner-strip { background-position: 100% 50%; }
.pf-banner-strip::before {
  content: ""; position: absolute; inset: 0;
  background-image: radial-gradient(rgba(255,255,255,.16) 1.5px, transparent 1.5px);
  background-size: 18px 18px;
  opacity: .55;
}
.pf-banner-blob { position: absolute; border-radius: 50%; background: rgba(255,255,255,.14); filter: blur(2px); }
.pf-banner-blob-a { width: 160px; height: 160px; right: -40px; top: -70px; }
.pf-banner-blob-b { width: 110px; height: 110px; right: 90px; bottom: -60px; background: rgba(255,255,255,.1); }
.pf-banner-content { padding: 24px 28px 28px; display: flex; flex-direction: column; gap: 14px; }
.pf-banner-name { font-size: 20px; font-weight: 800; margin: 0; color: #111318; }
.pf-banner-role { font-size: 13px; color: #6B7280; margin: 4px 0 0; }
.pf-banner-meta { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 4px; }
.pf-banner-badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 7px 15px; border-radius: 999px;
  background: rgba(59,130,246,.1); color: #3B82F6; font-size: 12px; font-weight: 700;
  transition: transform .25s ease, background .25s ease;
}
.pf-banner-badge:hover { transform: translateY(-2px) scale(1.03); background: rgba(59,130,246,.18); }
.pf-banner-badge-ghost { background: #fff; border: 1px solid rgba(199,199,199,.45); color: #111318; }
.pf-banner-badge-ghost svg { width: 14px; height: 14px; color: #3B82F6; }
.pf-banner-lead { font-size: 14.5px; line-height: 1.75; color: #111318; margin: 6px 0 0; max-width: 900px; }

/* Quick facts — one inline strip inside the banner, not separate stat cards */
.pf-banner-facts {
  display: flex; flex-wrap: wrap; align-items: center; gap: 20px;
  margin-top: 20px; padding-top: 20px; border-top: 1px solid rgba(199,199,199,.35);
}
.pf-banner-fact-divider { width: 1px; height: 28px; background: rgba(199,199,199,.45); }
.pf-banner-fact { display: inline-flex; align-items: center; gap: 10px; }
.pf-banner-fact-icon {
  width: 32px; height: 32px; border-radius: 10px; background: rgba(59,130,246,.1);
  color: #3B82F6; display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
.pf-banner-fact-icon svg { width: 16px; height: 16px; }
.pf-banner-fact-text { display: flex; flex-direction: column; line-height: 1.3; gap: 1px; }
.pf-banner-fact-text strong { font-size: 13px; font-weight: 800; color: #111318; }
.pf-banner-fact-text em { font-style: normal; font-size: 10.5px; color: #8A8F98; }


/* Career timeline — a taller, richer growth chart paired beside Experience. */
.pf-timeline-card {
  display: flex; flex-direction: column; gap: 20px; height: 100%; box-sizing: border-box;
  position: relative; overflow: hidden;
}
.pf-timeline-chart { position: relative; margin-top: 4px; padding-top: 6px; }
.pf-timeline-growth {
  display: inline-flex; align-items: center; gap: 6px; margin-bottom: 14px;
  padding: 6px 12px; border-radius: 999px; background: rgba(59,130,246,.08);
  font-size: 10.5px; font-weight: 800; color: #3B82F6; text-transform: uppercase; letter-spacing: .05em;
}
.pf-timeline-growth svg { width: 13px; height: 13px; }
.pf-timeline-svg { width: 100%; max-width: 100%; height: auto; display: block; aspect-ratio: 460 / 320; overflow: hidden; }
.pf-timeline-area { fill: rgba(59,130,246,.08); opacity: 0; animation: pf-fade-up .8s .5s ease forwards; }
.pf-timeline-guide { stroke: rgba(17,19,24,.08); stroke-width: 1; }
.pf-timeline-baseline { stroke: #C7C7C7; stroke-width: 1; }
.pf-timeline-hgrid { stroke: rgba(17,19,24,.07); stroke-width: 1; stroke-dasharray: 4 4; }
.pf-timeline-line {
  fill: none; stroke: #3B82F6; stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round;
  animation: pf-timeline-draw 1.2s .35s cubic-bezier(.4,0,.2,1) forwards;
}
@keyframes pf-timeline-draw { to { stroke-dashoffset: 0; } }
.pf-timeline-point {
  opacity: 0; animation: pf-pop-in .5s ease both;
  cursor: pointer; transition: transform .2s ease; outline: none;
}
.pf-timeline-point:hover, .pf-timeline-point.is-active { transform: scale(1.14); }
.pf-timeline-point:focus-visible .pf-timeline-dot { outline: 2px solid #3B82F6; outline-offset: 3px; border-radius: 50%; }
.pf-timeline-dot { fill: #3B82F6; stroke: #ECF1F4; stroke-width: 3.5; transition: r .2s ease, filter .2s ease; }
.pf-timeline-point.is-current .pf-timeline-dot { filter: drop-shadow(0 2px 3px rgba(59,130,246,.4)); }
.pf-timeline-point:hover .pf-timeline-dot, .pf-timeline-point.is-active .pf-timeline-dot { filter: brightness(1.1); }
.pf-timeline-point.is-current .pf-timeline-ring {
  fill: none; stroke: #3B82F6; stroke-width: 1.5; opacity: .55;
  animation: pf-timeline-pulse 2.2s ease-out infinite;
  transform-box: fill-box; transform-origin: center;
}
@keyframes pf-timeline-pulse { 0% { transform: scale(1); opacity: .5; } 100% { transform: scale(1.9); opacity: 0; } }
@keyframes pf-pop-in { from { opacity: 0; transform: scale(.5); } to { opacity: 1; transform: scale(1); } }
.pf-timeline-role { font-size: 12.5px; font-weight: 800; fill: #111318; }
.pf-timeline-year { font-size: 11px; font-weight: 700; fill: #8A8F98; letter-spacing: .03em; }

/* Pop-up info card for the active timeline point — positioned via % of the
   SVG's own viewBox, so it tracks the point at any responsive width. Clear
   hierarchy: small blue eyebrow (year) → bold title → muted meta line
   (divider-separated) → description. */
.pf-timeline-tooltip {
  position: absolute; z-index: 5; width: 280px; max-width: calc(100% - 16px);
  background: #fff; border: 1px solid rgba(199,199,199,.5); border-radius: 16px;
  box-shadow: 0 20px 40px rgba(122,122,122,.26); padding: 18px 20px;
  pointer-events: none; transform: translate(-50%, calc(-100% - 18px));
  animation: pf-tooltip-in .16s ease both;
  display: flex; flex-direction: column; gap: 6px;
}
.pf-timeline-tooltip.is-below { transform: translate(-50%, 18px); }
.pf-timeline-tooltip.align-start { transform: translate(0, calc(-100% - 18px)); }
.pf-timeline-tooltip.align-start.is-below { transform: translate(0, 18px); }
.pf-timeline-tooltip.align-end { transform: translate(-100%, calc(-100% - 18px)); }
.pf-timeline-tooltip.align-end.is-below { transform: translate(-100%, 18px); }
.pf-timeline-tooltip-eyebrow {
  font-size: 10.5px; font-weight: 800; color: #3B82F6; letter-spacing: .08em; text-transform: uppercase; margin: 0;
}
.pf-timeline-tooltip h4 { font-size: 16.5px; font-weight: 800; margin: 0; color: #111318; line-height: 1.3; }
.pf-timeline-tooltip-meta {
  font-size: 12px; font-weight: 600; color: #6B7280; margin: 2px 0 10px;
  padding-bottom: 10px; border-bottom: 1px solid rgba(199,199,199,.35);
}
.pf-timeline-tooltip-text { font-size: 12.5px; line-height: 1.7; color: #4B5563; margin: 0; }
@keyframes pf-tooltip-in { from { opacity: 0; } to { opacity: 1; } }

/* "How I Approach Design" — ONE card: Purpose and Intention sit side by
   side inside it, joined by a single connecting line down the middle. */
.pf-approach-section { display: flex; flex-direction: column; gap: 20px; }
.pf-approach-split { display: grid; grid-template-columns: 1fr auto 1fr; gap: 28px; align-items: stretch; margin-top: 2px; }
.pf-approach-connector { width: 1px; align-self: stretch; background: rgba(199,199,199,.5); }
.pf-approach-half {
  position: relative; display: flex; flex-direction: column; gap: 16px;
  opacity: 0; animation: pf-fade-up .5s ease forwards;
}
.pf-approach-half h3 { font-size: 18px; font-weight: 800; margin: 0; color: #111318; }
.pf-approach-desc { font-size: 13px; line-height: 1.75; color: #4B5563; margin: 0; }
.pf-approach-items { display: flex; flex-direction: column; gap: 12px; margin-top: 4px; padding-top: 16px; border-top: 1px solid rgba(199,199,199,.35); }
.pf-approach-item { display: flex; gap: 10px; align-items: baseline; }
.pf-approach-item-label { flex-shrink: 0; font-size: 12px; font-weight: 800; color: #3B82F6; min-width: 78px; }
.pf-approach-item-text { font-size: 12.5px; line-height: 1.6; color: #4B5563; }

/* Looping animated visual above each half — a pen "writing" a line for
   Purpose, blocks stacking up for Intention. Purely decorative (aria-hidden). */
.pf-approach-visual {
  position: relative; width: 100%; height: 104px; border-radius: 16px; overflow: hidden;
  background: linear-gradient(135deg, #3B82F6 0%, #2f6fe0 100%);
  display: flex; align-items: center; justify-content: center;
}
.pf-approach-pen-svg { width: 80%; height: 62%; overflow: visible; }
.pf-approach-pen-path {
  fill: none; stroke: rgba(255,255,255,.85); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round;
  /* pathLength="1" on the element normalizes the path's real length to 1,
     so this dash animation always lines up exactly with the nib's
     <animateMotion> percentage — the two can never drift apart regardless
     of how the curve itself is reshaped. */
  stroke-dasharray: 1; stroke-dashoffset: 1;
  animation: pf-pen-draw 5.5s ease-in-out infinite;
}
@keyframes pf-pen-draw {
  0% { stroke-dashoffset: 1; opacity: .35; }
  8% { opacity: 1; }
  60% { stroke-dashoffset: 0; opacity: 1; }
  78% { stroke-dashoffset: 0; opacity: 1; }
  94% { opacity: 0; }
  100% { stroke-dashoffset: 1; opacity: 0; }
}
/* The nib is an SVG shape moved by <animateMotion> along the SAME path the
   stroke draws, with rotate="auto" so it always points along the direction
   of travel — it traces the exact cursive line instead of a straight sweep. */
.pf-approach-pen-nib { fill: #fff; opacity: 0; animation: pf-pen-fade 5.5s ease-in-out infinite; }
.pf-approach-pen-nib-slit { fill: #3B82F6; opacity: .9; }
@keyframes pf-pen-fade {
  0% { opacity: 0; }
  8% { opacity: 1; }
  60% { opacity: 1; }
  78% { opacity: 1; }
  94% { opacity: 0; }
  100% { opacity: 0; }
}
.pf-approach-blocks {
  position: relative; width: 72px; height: 68px;
  display: flex; flex-direction: column-reverse; align-items: center; gap: 6px;
}
.pf-approach-block {
  height: 14px; border-radius: 4px; background: rgba(255,255,255,.92);
  opacity: 0; transform: translateY(18px) scale(.85);
  animation: pf-block-rise 3.2s ease-in-out infinite;
}
.pf-approach-block:nth-child(1) { width: 60px; animation-delay: 0s; }
.pf-approach-block:nth-child(2) { width: 46px; animation-delay: .35s; }
.pf-approach-block:nth-child(3) { width: 32px; animation-delay: .7s; }
@keyframes pf-block-rise {
  0% { opacity: 0; transform: translateY(18px) scale(.85); }
  14% { opacity: 1; transform: translateY(0) scale(1); }
  75% { opacity: 1; transform: translateY(0) scale(1); }
  92% { opacity: 0; transform: translateY(-6px) scale(.9); }
  100% { opacity: 0; transform: translateY(18px) scale(.85); }
}

/* Certifications — one card, one certificate at a time, arrows either side,
   a bullet below per certificate. Sits beside Career Progression, so it's
   pinned to the same fixed height/width as that card. */
.pf-cert-section { display: flex; flex-direction: column; gap: 20px; height: 100%; box-sizing: border-box; }
.pf-cert-slider { display: flex; align-items: center; gap: 16px; flex: 1; }
.pf-cert-arrow {
  flex-shrink: 0; width: 38px; height: 38px; border-radius: 50%;
  border: 1px solid rgba(199,199,199,.5); background: #fff; color: #111318;
  display: flex; align-items: center; justify-content: center; cursor: pointer;
  transition: transform .2s ease, border-color .2s ease, color .2s ease, background .2s ease;
}
.pf-cert-arrow svg { width: 16px; height: 16px; }
.pf-cert-arrow:hover { border-color: #3B82F6; color: #3B82F6; transform: translateY(-2px); }
.pf-cert-arrow:active { transform: translateY(0) scale(.95); }
.pf-cert-slide {
  flex: 1; min-width: 0; display: flex; flex-direction: column; align-items: center; gap: 8px;
  text-align: center; padding: 22px 20px; border-radius: 14px; border: 1px solid rgba(199,199,199,.4);
  animation: pf-fade-up .35s ease both;
}
.pf-cert-slide-image {
  width: 100%; max-width: 460px; border-radius: 10px; overflow: hidden;
  border: 1px solid rgba(199,199,199,.4); background: #fff; margin-bottom: 4px;
}
.pf-cert-slide-image img { width: 100%; height: auto; display: block; }
.pf-cert-slide-title { font-size: 14px; font-weight: 800; color: #111318; }
.pf-cert-slide-issuer { font-size: 12px; color: #6B7280; }
.pf-cert-slide-meta { font-size: 11px; color: #8A8F98; }
.pf-cert-bullets { display: flex; align-items: center; justify-content: center; gap: 9px; }
.pf-cert-bullet {
  width: 8px; height: 8px; border-radius: 50%; padding: 0; border: none; cursor: pointer;
  background: rgba(199,199,199,.6); transition: transform .2s ease, background .2s ease, width .2s ease;
}
.pf-cert-bullet:hover { background: rgba(59,130,246,.5); }
.pf-cert-bullet.active { background: #3B82F6; width: 22px; border-radius: 999px; }

/* Outside the Work — an auto-rotating 3-card carousel. The active card sits
   centered and scaled up; the other two peek from the sides and can be
   clicked to jump straight to them. */
.pf-outside-section { display: flex; flex-direction: column; gap: 20px; }
.pf-outside-carousel {
  position: relative; height: 480px; overflow: hidden; border-radius: 12px;
  display: flex; align-items: center; justify-content: center;
}
.pf-outside-card-item {
  position: absolute; top: 50%; left: 50%; width: 480px; min-height: 420px;
  padding: 20px; display: flex; flex-direction: column; align-items: flex-start; gap: 18px;
  text-align: left; font-family: inherit; cursor: pointer;
  background: #fff; border: 1px solid rgba(199,199,199,.45); border-radius: 20px;
  box-shadow: 0 6px 13px rgba(122,122,122,.10);
  transition: transform .6s cubic-bezier(.4,0,.2,1), opacity .6s ease, box-shadow .3s ease;
}
.pf-outside-card-item.is-center {
  transform: translate(-50%, -50%) translateX(0) scale(1.06);
  opacity: 1; z-index: 3; box-shadow: 0 18px 32px rgba(122,122,122,.2); cursor: default;
}
.pf-outside-card-item.is-left {
  transform: translate(-50%, -50%) translateX(-410px) scale(.8);
  opacity: .55; z-index: 1;
}
.pf-outside-card-item.is-right {
  transform: translate(-50%, -50%) translateX(410px) scale(.8);
  opacity: .55; z-index: 1;
}
.pf-outside-card-item.is-left:hover, .pf-outside-card-item.is-right:hover { opacity: .85; }
.pf-outside-card-item:focus-visible { outline: 2px solid #3B82F6; outline-offset: 4px; }
.pf-outside-card-image {
  width: 100%; height: 250px; border-radius: 16px; overflow: hidden; flex-shrink: 0;
  background: #DADFE3; display: flex; align-items: center; justify-content: center;
  transition: background .3s ease;
}
.pf-outside-card-image img, .pf-outside-card-image video { width: 100%; height: 100%; object-fit: cover; display: block; }
.pf-outside-card-image span { font-size: 11px; font-weight: 700; color: #6B7280; letter-spacing: .02em; }
.pf-outside-card-item:hover .pf-outside-card-image { background: #CDD5DB; }
.pf-outside-card-item-body { display: flex; align-items: center; gap: 8px; }
.pf-outside-icon {
  width: 30px; height: 30px; border-radius: 9px; background: rgba(59,130,246,.1);
  color: #3B82F6; display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}
.pf-outside-icon svg { width: 15px; height: 15px; }
.pf-outside-card-item h4 { font-size: 14px; font-weight: 800; margin: 0; color: #111318; }
.pf-outside-card-item p { font-size: 12px; line-height: 1.55; color: #6B7280; margin: 0; }


/* ---------- Responsive: small desktop / tablet landscape ---------- */
@media (max-width: 1100px) {
  /* PROJECTS no longer spans multiple rows at this width (it gets its own
     full-width row 1), so the row-1-pinning trick above doesn't apply —
     ABOUT/CONTACT have moved to row 2 instead, so that's the row pinned
     to their height here. */
  .pf-grid-inner { grid-template-columns: 1fr 1fr; grid-template-rows: auto 380px auto; }
  .pf-widget-projects { grid-column: 1 / 3; grid-row: 1; }
  .pf-widget-about { grid-column: 1; grid-row: 2; }
  .pf-widget-contact { grid-column: 2; grid-row: 2; }
  .pf-widget-cert { grid-column: 1 / 3; grid-row: 3; }
  .pf-about-columns { grid-template-columns: 1fr; }
  .pf-outside-carousel { height: 440px; }
  .pf-outside-card-item { width: 430px; min-height: 380px; padding: 20px; }
  .pf-outside-card-image { height: 220px; }
  .pf-outside-card-item.is-left { transform: translate(-50%, -50%) translateX(-365px) scale(.8); }
  .pf-outside-card-item.is-right { transform: translate(-50%, -50%) translateX(365px) scale(.8); }
}

/* ---------- Tablet & mobile: sidebar becomes a top header with a hamburger
   menu. Everything stacks in one column, in this order: the hamburger
   button (above the photo, toggles the dropdown below), the profile photo,
   the social icons right under it, then the nav dropdown — which now also
   holds the "Download my CV" action, below Contact, separated by a line.
   The in-page copyright footer (rendered at the end of <main>, see
   .pf-footer-mobile) takes over from the sidebar's own footer, which goes
   back to being desktop-only. ---------- */
@media (max-width: 1024px) {
  .pf-sidebar {
    position: relative;
    width: 100%;
    height: auto;
    /* The desktop rule sets overflow-y:auto/overflow-x:hidden for its own
       scrolling column — left in place here, it clips the floating nav
       dropdown below since abs-positioned children can't escape a clipping
       ancestor. Reset to visible so the dropdown can actually show. */
    overflow: visible;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    row-gap: 14px;
    padding: 20px 24px;
  }
  .pf-hamburger { display: flex; align-self: flex-start; order: 0; }
  /* Centered identity block — photo on top, name + role stacked and
     centered underneath, socials pulled in close right after. */
  .pf-photo-block { flex-direction: column; align-items: center; gap: 10px; order: 1; }
  .pf-photo-ring { width: 76px; height: 76px; }
  .pf-name-col { align-items: center; }
  .pf-name-row { margin-top: 0; }
  .pf-subtitle { text-align: center; margin-top: 2px; white-space: nowrap; max-width: none; }
  .pf-socials { margin-top: 4px; order: 2; justify-content: center; gap: 8px; }
  .pf-divider { display: none; }
  .pf-spacer { display: none; }
  .pf-cv-wrap-pinned { display: none; }
  .pf-footer { display: none; }
  /* Floating dropdown: positioned absolutely against the sidebar's own
     box, so opening it never pushes the page content below — it just
     overlays on top of whatever is already there. Anchored right under
     the hamburger button itself (padding-top + button height + a small
     gap) rather than the bottom of the whole header, so it doesn't drop
     all the way past the photo/name/socials block. */
  .pf-nav {
    position: absolute;
    top: 68px;
    left: 0;
    right: 0;
    display: none;
    width: auto;
    flex-direction: column;
    z-index: 40;
  }
  .pf-nav.open {
    display: flex;
    margin-top: 8px;
    padding: 10px;
    background: #fff;
    border: 1px solid rgba(199,199,199,.45);
    border-radius: 16px;
    box-shadow: 0 16px 34px rgba(17,19,24,.2);
    animation: pf-nav-in .22s ease;
  }
  .pf-nav.open .pf-nav-item { width: 100%; }
  .pf-nav-cv-divider {
    display: block; height: 1px; background: rgba(199,199,199,.5); margin: 10px 4px;
  }
  .pf-cv-wrap-inline { display: block; width: 100%; }
  .pf-footer-mobile { display: block; }
  .pf-main {
    margin-left: 0;
    width: 100%;
  }
}

/* ---------- Mobile: hamburger sits above the profile, nav collapses behind it ---------- */
@media (max-width: 720px) {
  .pf-hero h1 { font-size: 28px; }
  .pf-tools-bar { flex-direction: column; align-items: flex-start; gap: 14px; }
  .pf-tools-divider { display: none; }
  .pf-marquee-wrap { width: 100%; }
  .pf-grid-inner { grid-template-columns: 1fr; }
  .pf-widget-projects, .pf-widget-about, .pf-widget-contact, .pf-widget-cert {
    grid-column: 1 !important; grid-row: auto !important;
  }
  .pf-main { padding: 20px; }
  .pf-banner-content { padding: 16px 18px 20px; }
  .pf-banner-facts { gap: 10px; }
  .pf-approach-split { grid-template-columns: 1fr; gap: 20px; }
  .pf-approach-connector { width: 100%; height: 1px; }
  .pf-cert-slider { gap: 10px; }
  .pf-cert-slide { padding: 20px 12px; }
  .pf-outside-carousel { height: 400px; }
  .pf-outside-card-item { width: 380px; min-height: 350px; padding: 18px; gap: 14px; }
  .pf-outside-card-image { height: 190px; }
  .pf-outside-card-item.is-left { transform: translate(-50%, -50%) translateX(-320px) scale(.78); }
  .pf-outside-card-item.is-right { transform: translate(-50%, -50%) translateX(320px) scale(.78); }
  .pf-sidebar { padding: 14px 16px; row-gap: 12px; }
  .pf-nav { top: 62px; }
  .pf-envelope-shell { height: 585px; }
  .pf-envelope-frame { height: 170px; }
  .pf-envelope-content { top: 170px; }
  .pf-envelope-caption { padding: 0 28px; }
  .pf-envelope-open-title h3 { font-size: 16px; }
  .pf-letter-paper { padding: 20px 24px 24px; }
}

@keyframes pf-nav-in {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 480px) {
  .pf-hero h1 { font-size: 24px; }
  .pf-name { font-size: 15px; }
  .pf-subtitle { font-size: 10.5px; }
  .pf-photo-ring { width: 64px; height: 64px; }
  .pf-content-grid { padding: 14px; }
  .pf-card { padding: 16px; }
  .pf-tools-grid { grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 12px; }
  .pf-tool-card { height: 170px; }
  .pf-banner-strip { height: 96px; }
  .pf-banner-fact-divider { display: none; }
  .pf-cert-slider { flex-direction: column; }
  .pf-cert-arrow { align-self: center; }
  .pf-outside-carousel { height: 340px; }
  .pf-outside-card-item { width: 300px; min-height: 290px; padding: 14px; gap: 10px; }
  .pf-outside-card-image { height: 150px; }
  .pf-outside-card-item p { font-size: 11px; }
  .pf-outside-card-item.is-left { transform: translate(-50%, -50%) translateX(-250px) scale(.72); }
  .pf-outside-card-item.is-right { transform: translate(-50%, -50%) translateX(250px) scale(.72); }
  .pf-envelope-shell { height: 565px; }
  .pf-envelope-frame { height: 155px; }
  .pf-envelope-content { top: 155px; }
  .pf-envelope-open-title svg { width: 24px; height: 24px; }
  .pf-envelope-open-title h3 { font-size: 15px; }
  .pf-envelope-caption { padding: 0 22px; }
  .pf-envelope-caption h3 { font-size: 18px; }
  .pf-letter-paper { padding: 18px 20px 20px; }
}

@media (prefers-reduced-motion: reduce) {
  .pf-marquee-track { animation: none; }
  .pf-card, .pf-social, .pf-cv-btn, .pf-nav-item, .pf-tool-chip, .pf-photo-ring, .pf-widget-badge, .pf-placeholder,
  .pf-filter-chip, .pf-tool-card-inner, .pf-tool-card-icon, .pf-fav-btn,
  .pf-banner-strip, .pf-banner-badge, .pf-timeline-dot, .pf-cert-arrow, .pf-cert-bullet,
  .pf-outside-card-item, .pf-timeline-point, .pf-widget-media-overlay, .pf-widget-media-btn,
  .pf-widget-cert-thumb img, .pf-contact-mini, .pf-about-mini, .pf-about-mini-img {
    transition: none !important;
  }
  .pf-tool-card, .pf-about-body, .pf-timeline-point, .pf-timeline-line, .pf-timeline-area,
  .pf-approach-half, .pf-cert-slide {
    animation: none !important; opacity: 1 !important; stroke-dashoffset: 0 !important;
  }
  .pf-timeline-ring { animation: none !important; opacity: 0 !important; }
  .pf-approach-pen-path, .pf-approach-block { animation: none !important; opacity: 1 !important; stroke-dashoffset: 0 !important; transform: none !important; }
  .pf-approach-pen-nib { animation: none !important; opacity: 0 !important; }
  .pf-envelope-body, .pf-contact-confirm { animation: none !important; opacity: 1 !important; }
  .pf-envelope-flap, .pf-letter-paper, .pf-envelope-back,
  .pf-envelope-caption, .pf-envelope-shell { transition: none !important; }
  .pf-envelope-paper-plane { animation: none !important; opacity: 0 !important; }
  .pf-confirm-check path { animation: none !important; stroke-dashoffset: 0 !important; }
  .pf-contact-modal, .pf-contact-modal-panel { transition: none !important; }
  .pf-contact-quick-success { animation: none !important; opacity: 1 !important; }
  .pf-contact-quick-success-icon path { animation: none !important; stroke-dashoffset: 0 !important; }
  .pf-floating-icon { animation: none !important; }
}
`;

function GlobalStyles() {
  return <style>{GLOBAL_CSS}</style>;
}

// ---------------------------------------------------------------------------
// Small reusable "badge" icon — a rounded-square logo mark with initials,
// used for tools that don't need a full multi-path SVG mark.
// ---------------------------------------------------------------------------
function Badge({ bg, color = "#fff", text, gradientId }) {
  const fontSize = text.length > 2 ? 9.5 : 12;
  return (
    <svg viewBox="0 0 32 32" xmlns="http://www.w3.org/2000/svg">
      {gradientId && (
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stopColor="#00C4CC" />
            <stop offset="100%" stopColor="#7D2AE8" />
          </linearGradient>
        </defs>
      )}
      <rect width="32" height="32" rx="9" fill={gradientId ? `url(#${gradientId})` : bg} />
      <text
        x="16"
        y="20.5"
        textAnchor="middle"
        fontFamily="Poppins, sans-serif"
        fontWeight="700"
        fontSize={fontSize}
        fill={color}
      >
        {text}
      </text>
    </svg>
  );
}

