/* Subtle but plentiful drifting UI/UX/dev icons behind all page content.
   Purely decorative (aria-hidden). Each travels a real loop across a good
   chunk of the viewport (dx/dy are vw/vh, not px, so the trip is sized to
   the screen, not a small in-place wobble) with its own duration/delay/
   rotation so none of them move in sync. The first six use a pixel-based
   `left` inside the sidebar's own 260px-wide column (the sidebar's own
   background is transparent, so icons there really do show through) —
   without that, every icon's % position landed past the sidebar's edge
   and the sidebar looked bare next to a busier main area.
   NOTE: this must be declared after `const Icon = {...}` above (not before
   GlobalStyles(), where it originally lived) — it references Icon.Code etc.
   eagerly, at module-evaluation time, so declaring it earlier in the file
   than Icon itself throws "Cannot access 'Icon' before initialization". */
const FLOATING_ICON_ITEMS = [
  // --- inside / drifting through the sidebar column ---
  { Icon: Icon.Code, top: "10%", left: "40px", size: 26, dx: "4vw", dy: "9vh", dr: 10, duration: 24, delay: -3 },
  { Icon: Icon.Pen, top: "34%", left: "175px", size: 22, dx: "-5vw", dy: "7vh", dr: -9, duration: 27, delay: -12 },
  { Icon: Icon.Layers, top: "52%", left: "95px", size: 24, dx: "5vw", dy: "-8vh", dr: 8, duration: 21, delay: -6 },
  { Icon: Icon.Cpu, top: "68%", left: "205px", size: 20, dx: "-4vw", dy: "8vh", dr: -7, duration: 26, delay: -17 },
  { Icon: Icon.Compass, top: "86%", left: "60px", size: 24, dx: "4vw", dy: "-6vh", dr: 11, duration: 23, delay: -9 },
  { Icon: Icon.Search, top: "22%", left: "125px", size: 20, dx: "-3vw", dy: "10vh", dr: -8, duration: 29, delay: -20 },

  // --- across the rest of the page ---
  { Icon: Icon.Code, top: "6%", left: "30%", size: 30, dx: "10vw", dy: "8vh", dr: 10, duration: 26, delay: -2 },
  { Icon: Icon.Pen, top: "14%", left: "62%", size: 24, dx: "-9vw", dy: "11vh", dr: -8, duration: 30, delay: -9 },
  { Icon: Icon.Layers, top: "30%", left: "42%", size: 28, dx: "11vw", dy: "-9vh", dr: 8, duration: 24, delay: -14 },
  { Icon: Icon.Cpu, top: "40%", left: "82%", size: 26, dx: "-8vw", dy: "-7vh", dr: -10, duration: 32, delay: -5 },
  { Icon: Icon.Compass, top: "58%", left: "34%", size: 32, dx: "9vw", dy: "10vh", dr: 12, duration: 28, delay: -18 },
  { Icon: Icon.Search, top: "68%", left: "58%", size: 24, dx: "-10vw", dy: "8vh", dr: -6, duration: 22, delay: -11 },
  { Icon: Icon.Doc, top: "78%", left: "24%", size: 22, dx: "8vw", dy: "-11vh", dr: 7, duration: 33, delay: -7 },
  { Icon: Icon.Layers, top: "4%", left: "88%", size: 26, dx: "-8vw", dy: "9vh", dr: -9, duration: 27, delay: -20 },
  { Icon: Icon.Code, top: "88%", left: "70%", size: 24, dx: "9vw", dy: "-8vh", dr: 9, duration: 25, delay: -15 },
  { Icon: Icon.Pen, top: "48%", left: "22%", size: 20, dx: "-6vw", dy: "12vh", dr: -11, duration: 31, delay: -4 },
  { Icon: Icon.Compass, top: "20%", left: "78%", size: 22, dx: "7vw", dy: "-10vh", dr: 10, duration: 29, delay: -22 },
  { Icon: Icon.Cpu, top: "92%", left: "48%", size: 24, dx: "-7vw", dy: "-9vh", dr: -8, duration: 24, delay: -10 },
  { Icon: Icon.Doc, top: "62%", left: "8%", size: 22, dx: "6vw", dy: "9vh", dr: 9, duration: 30, delay: -13 },
  { Icon: Icon.Search, top: "10%", left: "48%", size: 20, dx: "-8vw", dy: "7vh", dr: -7, duration: 28, delay: -25 },
];

function FloatingIcons() {
  return (
    <div className="pf-floating-icons" aria-hidden="true">
      {FLOATING_ICON_ITEMS.map((item, i) => (
        <span
          key={i}
          className="pf-floating-icon"
          style={{
            top: item.top,
            left: item.left,
            width: item.size,
            height: item.size,
            animationDuration: `${item.duration}s`,
            animationDelay: `${item.delay}s`,
            "--dx": item.dx,
            "--dy": item.dy,
            "--dr": `${item.dr}deg`,
          }}
        >
          <item.Icon />
        </span>
      ))}
    </div>
  );
}

