function ImagePlaceholder({ height }) {
  return (
    <div className="pf-placeholder" style={{ height }}>
      <span>IMAGE WILL BE PLACED HERE</span>
    </div>
  );
}

function Widget({ className, title, description, icon: WidgetIcon, actionLabel, onAction, children }) {
  return (
    <div className={`pf-card pf-widget ${className}`}>
      <div className="pf-widget-header">
        <span className="pf-widget-badge">
          <WidgetIcon />
        </span>
        <h2>{title}</h2>
      </div>
      <p className="pf-widget-desc">{description}</p>
      {onAction ? (
        <div className="pf-widget-media">
          {children}
          <div className="pf-widget-media-overlay">
            <button type="button" className="pf-widget-media-btn" onClick={onAction}>
              <span>{actionLabel}</span>
              <Icon.ArrowRight />
            </button>
          </div>
        </div>
      ) : (
        children
      )}
    </div>
  );
}

// navigator.clipboard.writeText silently rejects in a lot of embedded/
// sandboxed preview contexts (no clipboard-write permission granted to the
// iframe) — awaiting it and only reacting on success meant the confirmation
// view never appeared there at all, with no error visible either. This
// legacy fallback (a temporary, invisible, selected textarea + a bare
// document.execCommand("copy")) covers most of those same "no Clipboard API
// / no permission" cases the modern API fails in, so the callers below use
// it wherever navigator.clipboard.writeText isn't available or throws.
function copyTextFallback(text) {
  try {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.top = "-1000px";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    document.execCommand("copy");
    document.body.removeChild(ta);
  } catch {
    // Best effort — some environments block this too, and there's nothing
    // further to try.
  }
}

// A tiny static preview of the closed envelope, used on the Home page's
// Contact widget in place of a plain placeholder. Clicking it gives a quick
// "pop" of its own before handing off to the same contact modal the sidebar
// opens, so it reads as the doorway into that envelope rather than a
// separate, disconnected button.
//
// The grid-placed element here is a plain <div> (className, the grid slot),
// with the actual <button> nested inside it — not the grid item itself.
// A <button> used directly as a CSS grid item doesn't reliably report its
// own explicit height to the grid's row-sizing math in every browser (its
// row can collapse to the height of one line of text instead), which is
// exactly why this card and the ABOUT one below were vanishing to a sliver
// on tablet/mobile. A non-form-control wrapper sidesteps that entirely.
function ContactPreviewCard({ onOpenContact, className = "" }) {
  const [growing, setGrowing] = React.useState(false);

  // Grow in place first (its own quick "pop"), then hand off to the modal —
  // which opens already mid-grow (see .pf-contact-modal-panel's own scale
  // transition) and, once open, plays the same closed -> opening -> open
  // flap animation the sidebar's envelope plays, instead of skipping straight
  // to the open letter. That "true" arg tells ContactModal to auto-trigger
  // the opening animation rather than waiting for another click.
  const handleClick = () => {
    setGrowing(true);
    window.setTimeout(() => {
      onOpenContact?.("closed", true);
      setGrowing(false);
    }, 180);
  };

  const [copied, setCopied] = React.useState(false);

  // A real shortcut, not just a readout: copies the email straight to the
  // clipboard so someone who'd rather paste it into their own mail app
  // never has to open the envelope at all.
  //
  // The confirmation view is shown as soon as this is clicked rather than
  // after awaiting navigator.clipboard.writeText — plenty of embedded/
  // sandboxed preview contexts (no clipboard-write permission granted to
  // the iframe) silently reject that call, which meant clicking Copy did
  // visibly nothing there at all. The actual copy still happens in the
  // background, trying the modern API first and falling back to the
  // legacy textarea+execCommand trick (copyTextFallback, above) when that
  // API is missing or rejects — between the two, this covers every
  // environment the modern-only version didn't.
  const handleCopyEmail = (e) => {
    e.stopPropagation();
    setCopied(true);
    // Longer than a typical one-word "Copied!" toast, since this one
    // actually has a sentence to read.
    window.setTimeout(() => setCopied(false), 3200);

    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(CONTACT_RECEIVER_EMAIL).catch(() => {
        copyTextFallback(CONTACT_RECEIVER_EMAIL);
      });
    } else {
      copyTextFallback(CONTACT_RECEIVER_EMAIL);
    }
  };

  return (
    <div className={className}>
      <button
        type="button"
        className={`pf-contact-mini${growing ? " is-growing" : ""}`}
        onClick={handleClick}
        aria-label="Open the contact form"
      >
        <span className="pf-contact-mini-flap" aria-hidden="true" />
        <span className="pf-contact-mini-badge" aria-hidden="true" />
        <span className="pf-contact-mini-tooltip" role="tooltip">
          Write me a message
        </span>
      </button>
      <div className="pf-contact-quick" aria-live="polite">
        {copied ? (
          <div className="pf-contact-quick-success">
            <span className="pf-contact-quick-success-icon" aria-hidden="true">
              <Icon.Check />
            </span>
            <p>My email was successfully copied to your clipboard — feel free to email me!</p>
          </div>
        ) : (
          <>
            <span className="pf-contact-quick-icon">
              <Icon.Mail />
            </span>
            <span className="pf-contact-quick-text">
              <strong>Prefer email?</strong>
              <span className="pf-contact-quick-email" title={CONTACT_RECEIVER_EMAIL}>
                {CONTACT_RECEIVER_EMAIL}
              </span>
            </span>
            <button type="button" className="pf-contact-quick-copy" onClick={handleCopyEmail}>
              <Icon.Copy />
              <span>Copy email</span>
            </button>
          </>
        )}
      </div>
    </div>
  );
}

const ABOUT_PREVIEW_ROTATE_MS = 4000;

// The Home page's About widget — like a photo card, not a text card: the
// "outside the work" photo/gif itself fills the whole tile, one at a time
// (cross-fading through the same set OutsideWork uses on the About page),
// with the heading, blurb and CTA sitting in a gradient overlay on top of
// it rather than above a separate image strip.
function AboutPreviewCard({ onNavigate, className = "" }) {
  const [index, setIndex] = React.useState(0);

  React.useEffect(() => {
    if (typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) {
      return undefined;
    }
    const t = window.setTimeout(() => {
      setIndex((i) => (i + 1) % outsideCycle.length);
    }, ABOUT_PREVIEW_ROTATE_MS);
    return () => window.clearTimeout(t);
  }, [index]);

  return (
    <div className={className}>
      <button
        type="button"
        className="pf-about-mini"
        onClick={() => onNavigate?.("about")}
        aria-label="See more about me"
      >
        <span className="pf-about-mini-media" aria-hidden="true">
          {outsideCycle.map((o, i) => (
            <img
              key={o.key}
              src={o.image}
              alt=""
              className={`pf-about-mini-img${i === index ? " is-active" : ""}`}
            />
          ))}
        </span>
        <span className="pf-about-mini-overlay">
          <span className="pf-about-mini-header">
            <span className="pf-about-mini-icon">
              <Icon.About />
            </span>
            <h3>About</h3>
          </span>
          <p>
            Get to know me — my background, how I approach design, and a few things I do outside of work.
          </p>
          <span className="pf-about-mini-btn">
            <span>See more</span>
            <Icon.ArrowRight />
          </span>
        </span>
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Sidebar
// ---------------------------------------------------------------------------
function Sidebar({ activeKey = "home", onNavigate, onOpenContact, contactOpen = false, profileImage }) {
  // Only used on narrow/mobile screens — the hamburger toggles this to show
  // or hide the nav dropdown, keeping the mobile header clean by default.
  const [navOpen, setNavOpen] = React.useState(false);

  // Every nav item navigates to its own page except Contact, which instead
  // opens the envelope as a modal over whatever page is already showing.
  const handleNav = (key) => {
    if (key === "contact") {
      onOpenContact?.();
    } else {
      onNavigate?.(key);
    }
    setNavOpen(false);
  };

  return (
    <aside className="pf-sidebar">
      {/* Mobile/tablet-only: toggles the nav dropdown below, and sits above
          the profile photo in that layout. Hidden on desktop, where the
          full nav is always visible instead. */}
      <button
        className="pf-hamburger"
        aria-label={navOpen ? "Close navigation" : "Open navigation"}
        aria-expanded={navOpen}
        onClick={() => setNavOpen((o) => !o)}
      >
        {navOpen ? <Icon.Close /> : <Icon.Menu />}
      </button>

      <div className="pf-photo-block">
        <div className="pf-photo-ring">
          <img src={profileImage || PROFILE_IMAGE} alt="Melvin Lomboy" />
        </div>
        <div className="pf-name-col">
          <div className="pf-name-row">
            <h3 className="pf-name">Melvin Lomboy</h3>
            <Icon.Verified />
          </div>
          <p className="pf-subtitle">UI/UX Designer | Product Designer | Design Engineer</p>
        </div>
      </div>

      <div className="pf-socials">
        {socials.map((s) => (
          <a key={s.key} href={s.href} aria-label={s.key} className="pf-social">
            <s.icon />
          </a>
        ))}
      </div>

      <div className="pf-divider" />

      <nav className={`pf-nav${navOpen ? " open" : ""}`}>
        {navItems.map((item) => {
          const active = item.key === "contact" ? contactOpen : item.key === activeKey;
          return (
            <button
              key={item.key}
              onClick={() => handleNav(item.key)}
              className={`pf-nav-item${active ? " active" : ""}`}
            >
              <item.icon />
              <span>{item.label}</span>
            </button>
          );
        })}
        {/* Tablet/mobile-only: the same CV action lives here, below Contact,
            separated by a line — the desktop version below (pf-cv-wrap-pinned)
            is hidden in that layout instead. */}
        <div className="pf-nav-cv-divider" aria-hidden="true" />
        <div className="pf-cv-wrap pf-cv-wrap-inline">
          <button className="pf-cv-btn">
            <Icon.Doc />
            <span>Download my CV</span>
          </button>
        </div>
      </nav>

      <div className="pf-spacer" />

      <div className="pf-cv-wrap pf-cv-wrap-pinned">
        <button className="pf-cv-btn">
          <Icon.Doc />
          <span>Download my CV</span>
        </button>
      </div>

      <div className="pf-divider" />

      <p className="pf-footer">© 2024 Melvin Lomboy. All rights reserved.</p>
    </aside>
  );
}

