// ---------------------------------------------------------------------------
// Tools section — an interactive, filterable, flip-card breakdown of the
// same tools shown in the Home marquee, grouped by category.
// ---------------------------------------------------------------------------
const toolCategories = ["All", "Design", "Development", "AI", "Productivity"];

function ToolsSection() {
  const [filter, setFilter] = React.useState("All");
  const [flipped, setFlipped] = React.useState(() => new Set());
  const [favorites, setFavorites] = React.useState(() => new Set());

  const toggleFlip = (key) => {
    setFlipped((prev) => {
      const next = new Set(prev);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    });
  };

  const toggleFavorite = (key, e) => {
    e.stopPropagation();
    setFavorites((prev) => {
      const next = new Set(prev);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    });
  };

  const filtered = filter === "All" ? tools : tools.filter((t) => t.category === filter);

  return (
    <section className="pf-tools-section">
      <div className="pf-filter-row">
        {toolCategories.map((cat) => (
          <button
            key={cat}
            className={`pf-filter-chip${filter === cat ? " active" : ""}`}
            onClick={() => setFilter(cat)}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* key={filter} remounts the grid on every filter change, which
          restarts the staggered entrance animation below. */}
      <div className="pf-tools-grid" key={filter}>
        {filtered.map((tool, i) => {
          const isFlipped = flipped.has(tool.key);
          const isFav = favorites.has(tool.key);
          return (
            <div
              key={tool.key}
              role="button"
              tabIndex={0}
              aria-pressed={isFlipped}
              className={`pf-tool-card${isFlipped ? " flipped" : ""}`}
              style={{ animationDelay: `${i * 45}ms` }}
              onClick={() => toggleFlip(tool.key)}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  toggleFlip(tool.key);
                }
              }}
            >
              <button
                type="button"
                className={`pf-fav-btn${isFav ? " active" : ""}`}
                onClick={(e) => toggleFavorite(tool.key, e)}
                aria-label={isFav ? `Remove ${tool.label} from favorites` : `Add ${tool.label} to favorites`}
              >
                <Icon.Star filled={isFav} />
              </button>

              <div className="pf-tool-card-inner">
                <div className="pf-tool-card-face pf-tool-card-front">
                  <span className="pf-tool-card-icon">
                    <tool.icon />
                  </span>
                  <h3>{tool.label}</h3>
                  <span className="pf-tool-card-tag">{tool.category}</span>
                </div>
                <div className="pf-tool-card-face pf-tool-card-back">
                  <p>{tool.blurb}</p>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

