const TIMELINE_TOP_Y = 32;
const TIMELINE_GRID_ROWS = 4;

function CareerTimeline() {
  const pts = timelinePoints;
  const baseY = TIMELINE_BASELINE_Y;
  // Horizontal reference lines spanning the full chart width, evenly spaced
  // from the top down to (but not including) the baseline — so it reads
  // like an actual progress graph instead of just a connected dot line.
  const hGridYs = Array.from({ length: TIMELINE_GRID_ROWS }, (_, i) => TIMELINE_TOP_Y + ((baseY - TIMELINE_TOP_Y) * i) / TIMELINE_GRID_ROWS);
  const linePath = pts.map((p, i) => `${i === 0 ? "M" : "L"}${p.x},${p.y}`).join(" ");
  const areaPath = `${linePath} L${pts[pts.length - 1].x},${baseY} L${pts[0].x},${baseY} Z`;
  const length = pts.slice(1).reduce((sum, p, i) => sum + Math.hypot(p.x - pts[i].x, p.y - pts[i].y), 0);
  const [activeIndex, setActiveIndex] = React.useState(null);
  const active = activeIndex !== null ? pts[activeIndex] : null;

  const show = (i) => setActiveIndex(i);
  const hide = (i) => setActiveIndex((cur) => (cur === i ? null : cur));
  const toggle = (i) => setActiveIndex((cur) => (cur === i ? null : i));

  return (
    <div className="pf-card pf-timeline-card">
      <div className="pf-widget-header">
        <span className="pf-widget-badge">
          <Icon.Certificate />
        </span>
        <h2>CAREER PROGRESSION</h2>
      </div>
      <p className="pf-widget-desc">Hover or tap a point on the graph to see the role, dates, and highlights.</p>
      <div className="pf-timeline-chart">
        <span className="pf-timeline-growth">
          <Icon.Team />
          Growth over time
        </span>
        <svg
          viewBox={`0 0 ${TIMELINE_VIEW.w} ${TIMELINE_VIEW.h}`}
          className="pf-timeline-svg"
          preserveAspectRatio="xMidYMid meet"
        >
          {hGridYs.map((y, i) => (
            <line key={`hgrid-${i}`} x1={0} y1={y} x2={TIMELINE_VIEW.w} y2={y} className="pf-timeline-hgrid" />
          ))}
          <path d={areaPath} className="pf-timeline-area" />
          <line x1={pts[0].x} y1={baseY} x2={pts[pts.length - 1].x} y2={baseY} className="pf-timeline-baseline" />
          {pts.map((p, i) => (
            <line key={`guide-${i}`} x1={p.x} y1={p.y} x2={p.x} y2={baseY} className="pf-timeline-guide" />
          ))}
          <path
            d={linePath}
            className="pf-timeline-line"
            style={{ strokeDasharray: length, strokeDashoffset: length }}
          />
          {pts.map((p, i) => (
            <g
              key={p.year + i}
              className={`pf-timeline-point${p.current ? " is-current" : ""}${activeIndex === i ? " is-active" : ""}`}
              style={{ animationDelay: `${0.55 + i * 0.18}s`, transformOrigin: `${p.x}px ${p.y}px` }}
              role="button"
              tabIndex={0}
              aria-label={`${p.detail.title}${p.detail.meta ? ` — ${p.detail.meta}` : ""}`}
              onMouseEnter={() => show(i)}
              onMouseLeave={() => hide(i)}
              onFocus={() => show(i)}
              onBlur={() => hide(i)}
              onClick={() => toggle(i)}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  toggle(i);
                }
              }}
            >
              {p.current && <circle cx={p.x} cy={p.y} r={p.r} className="pf-timeline-ring" />}
              <circle cx={p.x} cy={p.y} r={p.r} className="pf-timeline-dot" />
              <text x={p.x} y={p.y - p.r - 14} textAnchor="middle" className="pf-timeline-role">
                {p.role}
              </text>
              <text x={p.x} y={baseY + 24} textAnchor="middle" className="pf-timeline-year">
                {p.year}
              </text>
            </g>
          ))}
        </svg>

        {active && (
          <div
            className={`pf-timeline-tooltip${active.y / TIMELINE_VIEW.h < 0.3 ? " is-below" : ""}${
              active.x / TIMELINE_VIEW.w < 0.15 ? " align-start" : active.x / TIMELINE_VIEW.w > 0.85 ? " align-end" : ""
            }`}
            style={{
              left: `${(active.x / TIMELINE_VIEW.w) * 100}%`,
              top: `${(active.y / TIMELINE_VIEW.h) * 100}%`,
            }}
          >
            <p className="pf-timeline-tooltip-eyebrow">{active.year}</p>
            <h4>{active.detail.title}</h4>
            {active.detail.meta && <p className="pf-timeline-tooltip-meta">{active.detail.meta}</p>}
            {active.detail.text && <p className="pf-timeline-tooltip-text">{active.detail.text}</p>}
          </div>
        )}
      </div>
    </div>
  );
}

