// A continuous, connected-loop path standing in for cursive handwriting —
// the pen's nib is animated along this exact path (see ApproachSection),
// so it traces the same line the stroke draws rather than sweeping past it.
const PEN_CURSIVE_PATH =
  "M6,40 C20,10 46,10 58,34 C68,54 94,58 108,32 " +
  "C120,10 150,8 165,30 C176,46 186,42 194,26";

function ApproachSection() {
  const [reducedMotion, setReducedMotion] = React.useState(false);
  React.useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return undefined;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mq.matches);
    const handler = () => setReducedMotion(mq.matches);
    mq.addEventListener ? mq.addEventListener("change", handler) : mq.addListener(handler);
    return () => (mq.removeEventListener ? mq.removeEventListener("change", handler) : mq.removeListener(handler));
  }, []);

  return (
    <div className="pf-card pf-approach-section">
      <div className="pf-widget-header">
        <span className="pf-widget-badge">
          <Icon.Pen />
        </span>
        <h2>HOW I APPROACH DESIGN</h2>
      </div>
      <p className="pf-widget-desc">The two principles that shape every design decision I make.</p>
      <div className="pf-approach-split">
        {approachCards.map((c, i) => (
          <React.Fragment key={c.key}>
            {i > 0 && <span className="pf-approach-connector" aria-hidden="true" />}
            <div className="pf-approach-half" style={{ animationDelay: `${i * 0.1}s` }}>
              <div className="pf-approach-visual" aria-hidden="true">
                {c.visual === "pen" ? (
                  <svg className="pf-approach-pen-svg" viewBox="0 0 200 70">
                    <path
                      id={`pf-pen-path-${c.key}`}
                      className="pf-approach-pen-path"
                      d={PEN_CURSIVE_PATH}
                      pathLength="1"
                    />
                    <g className="pf-approach-pen-nib">
                      <path d="M-17,-2.4 L5,-2.4 Q16,-2.4 17,0 Q16,2.4 5,2.4 L-17,2.4 Z" />
                      <path className="pf-approach-pen-nib-slit" d="M4,-2 L15,0 L4,2 Z" />
                      {!reducedMotion && (
                        <animateMotion
                          dur="5.5s"
                          repeatCount="indefinite"
                          rotate="auto"
                          calcMode="linear"
                          keyTimes="0;0.6;0.78;1"
                          keyPoints="0;1;1;0"
                        >
                          <mpath href={`#pf-pen-path-${c.key}`} xlinkHref={`#pf-pen-path-${c.key}`} />
                        </animateMotion>
                      )}
                    </g>
                  </svg>
                ) : (
                  <div className="pf-approach-blocks">
                    <span className="pf-approach-block" />
                    <span className="pf-approach-block" />
                    <span className="pf-approach-block" />
                  </div>
                )}
              </div>
              <h3>{c.title}</h3>
              <p className="pf-approach-desc">{c.description}</p>
              <div className="pf-approach-items">
                {c.items.map((it) => (
                  <div className="pf-approach-item" key={it.label}>
                    <span className="pf-approach-item-label">{it.label}</span>
                    <span className="pf-approach-item-text">{it.text}</span>
                  </div>
                ))}
              </div>
            </div>
          </React.Fragment>
        ))}
      </div>
    </div>
  );
}

