function CertificationsCollage() {
  const [index, setIndex] = React.useState(0);
  const total = certifications.length;
  const current = certifications[index];

  const goTo = (i) => setIndex((i + total) % total);
  const prev = () => goTo(index - 1);
  const next = () => goTo(index + 1);

  return (
    <div className="pf-card pf-cert-section">
      <div className="pf-widget-header">
        <span className="pf-widget-badge">
          <Icon.Certificate />
        </span>
        <h2>CERTIFICATIONS</h2>
      </div>
      <p className="pf-widget-desc">Courses and credentials that continue to shape how I design and build.</p>

      <div className="pf-cert-slider">
        <button type="button" className="pf-cert-arrow" onClick={prev} aria-label="Previous certificate">
          <Icon.ArrowRight style={{ transform: "rotate(180deg)" }} />
        </button>

        <div className="pf-cert-slide" key={current.id}>
          <div className="pf-cert-slide-image">
            <img src={current.image} alt={`${current.title} certificate`} />
          </div>
          <span className="pf-cert-slide-title">{current.title}</span>
          <span className="pf-cert-slide-issuer">{current.issuer}</span>
          <span className="pf-cert-slide-meta">{current.meta}</span>
        </div>

        <button type="button" className="pf-cert-arrow" onClick={next} aria-label="Next certificate">
          <Icon.ArrowRight />
        </button>
      </div>

      <div className="pf-cert-bullets">
        {certifications.map((c, i) => (
          <button
            key={c.id}
            type="button"
            className={`pf-cert-bullet${i === index ? " active" : ""}`}
            onClick={() => goTo(i)}
            aria-label={`Show certificate ${i + 1}`}
          />
        ))}
      </div>
    </div>
  );
}

