// ---------------------------------------------------------------------------
// Placeholder shown for Projects until it gets its real content — just the
// title (via Hero) plus an empty widget card.
// ---------------------------------------------------------------------------
function BlankSection() {
  return <section className="pf-card pf-blank-section" />;
}

// ---------------------------------------------------------------------------
// Contact — an envelope you click open, write a note in, and send.
//
// This file has no backend of its own. Real delivery to
// lomboy.melvin255@gmail.com uses EmailJS (emailjs.com, free tier), which
// sends straight from the visitor's browser — no server required. To turn
// it on: create a free EmailJS account, add an Email Service (e.g. connect
// the Gmail this should land in) and an Email Template with
// {{from_email}}, {{subject}} and {{message}} variables, then paste the
// three IDs from your EmailJS dashboard into the constants below.
//
// Until those are filled in, the form still works — clicking Send opens
// the visitor's own email app with the message pre-filled to
// CONTACT_RECEIVER_EMAIL, via a plain mailto: link, and they hit send
// there. No fabricated "delivered" state either way — the confirmation
// message says which of the two actually happened.
// ---------------------------------------------------------------------------
const CONTACT_RECEIVER_EMAIL = "lomboy.melvin255@gmail.com";
const EMAILJS_SERVICE_ID = "service_k8ecjgc";
const EMAILJS_TEMPLATE_ID = "template_nc1d1nc"; // from the "Contact Us" template's Settings tab
const EMAILJS_PUBLIC_KEY = "Sk6V2rJSeX5WUMTdg";
const EMAILJS_CONFIGURED =
  EMAILJS_SERVICE_ID !== "YOUR_SERVICE_ID" &&
  EMAILJS_TEMPLATE_ID !== "YOUR_TEMPLATE_ID" &&
  EMAILJS_PUBLIC_KEY !== "YOUR_PUBLIC_KEY";

let emailjsLoadPromise = null;
function loadEmailJs() {
  if (typeof window === "undefined") return Promise.reject(new Error("no window"));
  if (window.emailjs) return Promise.resolve(window.emailjs);
  if (emailjsLoadPromise) return emailjsLoadPromise;
  emailjsLoadPromise = new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = "https://cdn.jsdelivr.net/npm/@emailjs/browser@4/dist/email.min.js";
    script.async = true;
    script.onload = () => {
      if (window.emailjs) {
        window.emailjs.init({ publicKey: EMAILJS_PUBLIC_KEY });
        resolve(window.emailjs);
      } else {
        reject(new Error("EmailJS failed to load"));
      }
    };
    script.onerror = () => reject(new Error("Could not load the EmailJS script"));
    document.head.appendChild(script);
  });
  return emailjsLoadPromise;
}

function ContactSection({ initialStage = "closed", autoOpen = false } = {}) {
  // closed -> opening -> open -> sending -> sent (or back to "open" on error)
  const [stage, setStage] = React.useState(initialStage);
  const [form, setForm] = React.useState({ subject: "", email: "", message: "" });
  const [errorMsg, setErrorMsg] = React.useState("");
  const [deliveredVia, setDeliveredVia] = React.useState(null); // "emailjs" | "mailto"

  const openEnvelope = () => {
    setStage("opening");
    // Switches to "open" (revealing the letter) a little before the flap's
    // own .6s rotation finishes, so the letter starts sliding up while the
    // flap is still finishing its last bit of motion — one continuous
    // gesture rather than "flap stops, then letter starts".
    window.setTimeout(() => setStage("open"), 480);
  };

  // When opened from the Home page's envelope preview, the modal itself is
  // already mid-"grow" by the time this mounts — so give that grow a beat to
  // read, then play the same closed -> opening -> open flap animation the
  // sidebar's envelope always plays, rather than arriving already open.
  React.useEffect(() => {
    if (!autoOpen || initialStage !== "closed") return undefined;
    const t = window.setTimeout(() => openEnvelope(), 420);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleEnvelopeKeyDown = (e) => {
    if (stage !== "closed") return;
    if (e.key === "Enter" || e.key === " " || e.key === "Spacebar") {
      e.preventDefault();
      openEnvelope();
    }
  };

  const resetForm = () => {
    setStage("closed");
    setForm({ subject: "", email: "", message: "" });
    setErrorMsg("");
    setDeliveredVia(null);
  };

  const handleChange = (key) => (e) => {
    const { value } = e.target;
    setForm((f) => ({ ...f, [key]: value }));
  };

  const handleSend = async (e) => {
    e.preventDefault();
    if (!form.email.trim() || !form.message.trim()) {
      setErrorMsg("Please fill in your email and message before sending.");
      return;
    }
    setErrorMsg("");
    setStage("sending");

    if (EMAILJS_CONFIGURED) {
      try {
        const emailjs = await loadEmailJs();
        // Field names here must match this account's actual EmailJS
        // template variables — its "Contact Us" template uses {{title}},
        // {{name}}, {{time}} and {{message}}, and its Reply To is set to
        // {{email}} so replying in Gmail goes straight back to the
        // visitor. The template's own "To Email" is already fixed to
        // CONTACT_RECEIVER_EMAIL, so that doesn't need to be sent here.
        await emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, {
          title: form.subject.trim() || "(No subject)",
          name: form.email.trim(),
          email: form.email.trim(),
          time: new Date().toLocaleString(),
          message: form.message.trim(),
        });
        setDeliveredVia("emailjs");
        setStage("sent");
      } catch (err) {
        // Logged so the actual EmailJS failure reason (bad IDs, blocked
        // domain, network issue, etc.) is visible in devtools, even though
        // the visitor only sees the friendly message below.
        console.error("EmailJS send failed:", err);
        setErrorMsg("Something went wrong sending that — please try again, or email me directly.");
        setStage("open");
      }
    } else {
      // No EmailJS account wired in yet — fall back to the visitor's own
      // email client via mailto:, after letting the send animation play.
      const mailto =
        `mailto:${CONTACT_RECEIVER_EMAIL}` +
        `?subject=${encodeURIComponent(form.subject.trim() || "Portfolio contact")}` +
        `&body=${encodeURIComponent(`${form.message.trim()}\n\n— from ${form.email.trim()}`)}`;
      window.setTimeout(() => {
        window.location.href = mailto;
        setDeliveredVia("mailto");
        setStage("sent");
      }, 900);
    }
  };

  const isClosed = stage === "closed";

  return (
    <div className={`pf-contact-stage stage-${stage}`}>
      {stage !== "sent" && (
        <div className="pf-envelope-scene">
          {/* Same DOM for every non-"sent" stage: closed, opening, open and
              sending all share this one envelope so it's a single object
              animating open, not two different-looking pieces swapped in. */}
          <div
            className="pf-envelope-body"
            onClick={isClosed ? openEnvelope : undefined}
            onKeyDown={isClosed ? handleEnvelopeKeyDown : undefined}
            role={isClosed ? "button" : undefined}
            tabIndex={isClosed ? 0 : undefined}
            aria-label={isClosed ? "Open envelope to write me a message" : undefined}
          >
            <div className="pf-envelope-shell">
              <div className="pf-envelope-frame">
                <div className="pf-envelope-back" />
                {/* Hidden behind the closed flap, revealed only once it
                    swings open — the "payoff" that makes the opening
                    motion register instead of just uncovering empty blue. */}
                <div className="pf-envelope-open-title" aria-hidden={isClosed}>
                  <Icon.Mail />
                  <h3>Go ahead, write your message below</h3>
                  <p>Expect a reply soon after you send it</p>
                </div>
                <div className="pf-envelope-flap" />
              </div>
              <div className="pf-envelope-content">
                <div className="pf-envelope-caption" aria-hidden={!isClosed}>
                  <h3>Let's get in touch</h3>
                  <p>
                    Click the envelope to send me a message — I'll get it at{" "}
                    <a href={`mailto:${CONTACT_RECEIVER_EMAIL}`} onClick={(e) => e.stopPropagation()}>
                      {CONTACT_RECEIVER_EMAIL}
                    </a>
                    .
                  </p>
                </div>
                <div className="pf-letter-paper" aria-hidden={isClosed}>
                  <form className="pf-letter-form" onSubmit={handleSend} noValidate>
                    <label className="pf-letter-field">
                      <span>Subject</span>
                      <input
                        type="text"
                        value={form.subject}
                        onChange={handleChange("subject")}
                        placeholder="What's this about?"
                        disabled={isClosed || stage === "sending"}
                        tabIndex={isClosed ? -1 : undefined}
                      />
                    </label>
                    <label className="pf-letter-field">
                      <span>Your email</span>
                      <input
                        type="email"
                        required
                        value={form.email}
                        onChange={handleChange("email")}
                        placeholder="you@email.com"
                        disabled={isClosed || stage === "sending"}
                        tabIndex={isClosed ? -1 : undefined}
                      />
                    </label>
                    <label className="pf-letter-field">
                      <span>Message</span>
                      <textarea
                        required
                        rows={4}
                        value={form.message}
                        onChange={handleChange("message")}
                        placeholder="Write your message..."
                        disabled={isClosed || stage === "sending"}
                        tabIndex={isClosed ? -1 : undefined}
                      />
                    </label>
                    {errorMsg && <p className="pf-contact-error">{errorMsg}</p>}
                    <div className="pf-letter-actions">
                      <button
                        type="button"
                        className="pf-letter-cancel"
                        onClick={resetForm}
                        disabled={isClosed || stage === "sending"}
                        tabIndex={isClosed ? -1 : undefined}
                      >
                        Cancel
                      </button>
                      <button
                        type="submit"
                        className="pf-cv-btn pf-send-btn"
                        disabled={isClosed || stage === "sending"}
                        tabIndex={isClosed ? -1 : undefined}
                      >
                        <Icon.Send />
                        <span>{stage === "sending" ? "Sending..." : "Send Message"}</span>
                      </button>
                    </div>
                  </form>
                </div>
              </div>
            </div>
            {stage === "sending" && (
              <span className="pf-envelope-paper-plane" aria-hidden="true">
                <Icon.Send />
              </span>
            )}
          </div>
        </div>
      )}

      {stage === "sent" && (
        <div className="pf-contact-confirm">
          <span className="pf-confirm-check" aria-hidden="true">
            <Icon.Check />
          </span>
          <h3>Message sent!</h3>
          <p>
            {deliveredVia === "emailjs"
              ? "Thanks for reaching out — I'll get back to you soon."
              : "Your email app should have opened with the message ready to go — hit send there to deliver it."}
          </p>
          <button type="button" className="pf-cv-btn pf-contact-again" onClick={resetForm}>
            <Icon.Mail />
            <span>Send another message</span>
          </button>
        </div>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Contact modal — wraps ContactSection in an overlay so Contact opens as a
// dialog over whatever page is already showing, instead of navigating to a
// page of its own. Mounting is staggered a frame behind `open` (and
// unmounting is delayed past `open` going false) purely so the backdrop and
// panel have something to transition from/to — CSS can't animate an element
// that isn't in the DOM yet. Unmounting ContactSection on close also resets
// the envelope back to its closed state for next time, for free, since it's
// a fresh component instance each time the modal reopens.
// ---------------------------------------------------------------------------
function ContactModal({ open, onClose, initialStage = "closed", autoOpen = false }) {
  const [mounted, setMounted] = React.useState(false);
  const [visible, setVisible] = React.useState(false);

  React.useEffect(() => {
    if (open) {
      setMounted(true);
      const raf = window.requestAnimationFrame(() => setVisible(true));
      return () => window.cancelAnimationFrame(raf);
    }
    setVisible(false);
    const t = window.setTimeout(() => setMounted(false), 280);
    return () => window.clearTimeout(t);
  }, [open]);

  React.useEffect(() => {
    if (!mounted) return undefined;
    const onKeyDown = (e) => {
      if (e.key === "Escape") onClose?.();
    };
    document.addEventListener("keydown", onKeyDown);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = prevOverflow;
    };
  }, [mounted, onClose]);

  if (!mounted) return null;

  return (
    <div
      className={`pf-contact-modal${visible ? " is-visible" : ""}`}
      onClick={onClose}
      role="presentation"
    >
      <div
        className="pf-contact-modal-panel"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label="Send a message"
      >
        <button type="button" className="pf-contact-modal-close" onClick={onClose} aria-label="Close">
          <Icon.Close />
        </button>
        <ContactSection initialStage={initialStage} autoOpen={autoOpen} />
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Page
// ---------------------------------------------------------------------------
export default function PortfolioPage({ profileImage }) {
  const [active, setActive] = React.useState("home");
  const [contactOpen, setContactOpen] = React.useState(false);
  // Both the sidebar and the Home page's envelope preview always open the
  // envelope closed, so the same flap-opening animation always plays. The
  // difference is who triggers it: the sidebar waits for a click inside the
  // modal, while the Home page preview has already "asked" by being clicked,
  // so autoOpen tells the modal to open the envelope itself once it's up.
  const [contactStage, setContactStage] = React.useState("closed");
  const [contactAutoOpen, setContactAutoOpen] = React.useState(false);

  const openContact = (stage = "closed", autoOpen = false) => {
    setContactStage(stage);
    setContactAutoOpen(autoOpen);
    setContactOpen(true);
  };

  return (
    <div className="pf-root">
      <GlobalStyles />
      <FloatingIcons />
      <Sidebar
        activeKey={active}
        onNavigate={setActive}
        onOpenContact={() => openContact("closed")}
        contactOpen={contactOpen}
        profileImage={profileImage}
      />
      <main className="pf-main">
        <Hero active={active} />
        {active === "home" ? (
          <>
            <ToolsBar />
            <ContentGrid onNavigate={setActive} onOpenContact={openContact} />
          </>
        ) : active === "tools" ? (
          <ToolsSection />
        ) : active === "about" ? (
          <AboutSection />
        ) : (
          <BlankSection />
        )}
        <p className="pf-footer-mobile">© 2024 Melvin Lomboy. All rights reserved.</p>
      </main>
      <ContactModal
        open={contactOpen}
        onClose={() => setContactOpen(false)}
        initialStage={contactStage}
        autoOpen={contactAutoOpen}
      />
    </div>
  );
}